/** Date + reading-time formatting shared across cards and article pages. */

export function formatDate(iso: string, locale = "en"): string {
  return new Intl.DateTimeFormat(locale, {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(new Date(iso));
}

export function formatDateTime(iso: string, locale = "en"): string {
  return new Intl.DateTimeFormat(locale, {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(iso));
}

/** Compact relative label, e.g. "2h ago". Static-friendly (computed at build). */
export function relativeTime(iso: string, now = Date.now()): string {
  const diffMs = now - new Date(iso).getTime();
  const minutes = Math.max(0, Math.round(diffMs / 60000));
  if (minutes < 1) return "just now";
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.round(hours / 24);
  if (days < 7) return `${days}d ago`;
  const weeks = Math.round(days / 7);
  if (weeks < 5) return `${weeks}w ago`;
  return formatDate(iso);
}

/** Approximate reading time for a block-based article. */
export function readingMinutes(content: { type: string; text?: string; items?: string[] }[]): number {
  const words = content.reduce((total, block) => {
    if ("text" in block && typeof block.text === "string") {
      return total + block.text.split(/\s+/).length;
    }
    if ("items" in block && Array.isArray(block.items)) {
      return total + block.items.join(" ").split(/\s+/).length;
    }
    return total;
  }, 0);
  return Math.max(1, Math.round(words / 200));
}

export function toISO(date: Date): string {
  return date.toISOString();
}

import type { Article, StatusTag } from "@/content/types";
import { relativeTime } from "@/lib/format";

/** Build the status tag for an article. "UPDATED" is derived from updatedAt. */
export function getStatusTag(article: Article): StatusTag | null {
  if (article.status === "breaking") return { kind: "breaking", label: "Breaking" };
  if (article.status === "live") return { kind: "live", label: "Live" };
  if (article.status === "trending") return { kind: "trending", label: "Trending" };
  if (article.status === "updated" && article.updatedAt) {
    return { kind: "updated", minutesAgo: Math.round((Date.now() - new Date(article.updatedAt).getTime()) / 60000) };
  }
  if (article.updatedAt) {
    return { kind: "updated", minutesAgo: Math.round((Date.now() - new Date(article.updatedAt).getTime()) / 60000) };
  }
  return null;
}

function labelFor(tag: StatusTag): string {
  switch (tag.kind) {
    case "live":
      return tag.label.toUpperCase();
    case "breaking":
      return tag.label.toUpperCase();
    case "trending":
      return tag.label.toUpperCase();
    case "updated":
      return `UPDATED ${relativeTimeFromMinutes(tag.minutesAgo).toUpperCase()}`;
  }
}

function relativeTimeFromMinutes(minutes: number): string {
  if (minutes < 1) return "just now";
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.round(hours / 24)}d ago`;
}

const DOT_CLASS: Record<StatusTag["kind"], string> = {
  live: "status-dot is-live",
  breaking: "status-dot is-breaking",
  updated: "status-dot is-updated",
  trending: "status-dot is-trending",
};

/**
 * Signature element — small colored dot + mono label encoding real recency
 * information. Amber is reserved for live/breaking/updated; blue for trending.
 */
export function StatusTag({ tag, size = "sm" }: { tag: StatusTag; size?: "sm" | "lg" }) {
  const sizeClass = size === "lg" ? "text-[0.72rem] gap-2" : "text-[0.62rem] gap-1.5";
  return (
    <span
      className={`inline-flex items-center font-mono font-semibold uppercase tracking-[0.14em] ${sizeClass}`}
      style={{ color: tag.kind === "trending" ? "var(--signal-ink)" : "var(--amber)" }}
    >
      <span className={DOT_CLASS[tag.kind]} aria-hidden="true" />
      {labelFor(tag)}
    </span>
  );
}

import type { ArticleImage } from "@/content/types";

/**
 * Deterministic, dependency-free cover art.
 *
 * Renders an abstract "broadcast still" — navy control-room background,
 * right-angle PCB circuit traces and a category accent — seeded from the
 * article slug so it never changes between deploys. No external images,
 * no image-optimization pipeline, crisp at any size.
 */

const TONES: Record<string, { accent: string; label: string }> = {
  ai: { accent: "#3B5BFF", label: "AI" },
  software: { accent: "#7C5CFF", label: "SOFTWARE" },
  security: { accent: "#2FBF8F", label: "SECURITY" },
  gadgets: { accent: "#FF7A59", label: "GADGETS" },
  cloud: { accent: "#3BB4FF", label: "CLOUD" },
  reviews: { accent: "#FFB020", label: "REVIEWS" },
  guides: { accent: "#4AD2A6", label: "GUIDES" },
  live: { accent: "#FFB020", label: "LIVE" },
  generic: { accent: "#3B5BFF", label: "AI TECH" },
};

/** Mulberry32 — tiny deterministic PRNG so art is stable per seed. */
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hashString(str: string): number {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function Traces({ seed, accent }: { seed: string; accent: string }) {
  const rnd = mulberry32(hashString(seed) ^ 0x9e3779b9);
  const traces: React.ReactNode[] = [];
  const W = 1200;
  const H = 630;
  for (let i = 0; i < 9; i++) {
    const startX = Math.round(rnd() * W);
    const startY = Math.round(rnd() * H);
    const segments = 2 + Math.floor(rnd() * 3);
    let x = startX;
    let y = startY;
    let d = `M${x} ${y}`;
    for (let s = 0; s < segments; s++) {
      if (rnd() > 0.5) {
        x += Math.round((rnd() - 0.2) * 260);
      } else {
        y += Math.round((rnd() - 0.2) * 260);
      }
      d += ` L${Math.max(0, Math.min(W, x))} ${Math.max(0, Math.min(H, y))}`;
    }
    traces.push(
      <g key={i}>
        <path d={d} fill="none" stroke={accent} strokeOpacity={0.16} strokeWidth={2} />
        <circle cx={Math.max(0, Math.min(W, x))} cy={Math.max(0, Math.min(H, y))} r={5} fill={accent} fillOpacity={0.35} />
      </g>,
    );
  }
  return <>{traces}</>;
}

export function CoverArt({
  image,
  seed,
  className,
}: {
  image: ArticleImage;
  seed: string;
  className?: string;
}) {
  const tone = TONES[image.cover] ?? TONES.generic;
  return (
    <svg
      viewBox="0 0 1200 630"
      role="img"
      aria-label={image.alt}
      className={className}
      preserveAspectRatio="xMidYMid slice"
    >
      <defs>
        <linearGradient id={`bg-${seed}`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#12131C" />
          <stop offset="100%" stopColor="#1A1D2E" />
        </linearGradient>
        <radialGradient id={`glow-${seed}`} cx="72%" cy="22%" r="80%">
          <stop offset="0%" stopColor={tone.accent} stopOpacity="0.28" />
          <stop offset="100%" stopColor={tone.accent} stopOpacity="0" />
        </radialGradient>
        <pattern id={`grid-${seed}`} width="44" height="44" patternUnits="userSpaceOnUse">
          <path d="M44 0H0V44" fill="none" stroke="#8891A6" strokeOpacity="0.12" strokeWidth="1" />
        </pattern>
      </defs>

      <rect width="1200" height="630" fill={`url(#bg-${seed})`} />
      <rect width="1200" height="630" fill={`url(#glow-${seed})`} />
      <rect width="1200" height="630" fill={`url(#grid-${seed})`} />
      <Traces seed={seed} accent={tone.accent} />

      {/* accent bars */}
      <rect x="0" y="0" width="1200" height="6" fill={tone.accent} />
      <rect x="86" y="470" width="14" height="120" fill={tone.accent} opacity="0.9" />
      <rect x="108" y="500" width="6" height="90" fill={tone.accent} opacity="0.45" />

      {/* signal block */}
      <rect x="86" y="60" width="10" height="10" fill={tone.accent} />
      <rect x="104" y="78" width="6" height="6" fill={tone.accent} opacity="0.5" />

      {/* label */}
      <text
        x="86"
        y="566"
        fontFamily="IBM Plex Mono, monospace"
        fontSize="30"
        letterSpacing="10"
        fill="#8891A6"
      >
        {tone.label}
      </text>
      <text
        x="86"
        y="438"
        fontFamily="'Big Shoulders Display', sans-serif"
        fontSize="120"
        fontWeight="800"
        fill="#F2F3F7"
        opacity="0.9"
      >
        AI TECH
      </text>
    </svg>
  );
}

