import type { ArticleSource } from "@/content/types";

/**
 * Sources block — required element for AI/tech news. Claims are linked to
 * their origin rather than left unsourced.
 */
export function SourcesBlock({ sources }: { sources: ArticleSource[] }) {
  return (
    <section className="mt-10 rounded-xl border border-line bg-surface p-5" aria-label="Sources">
      <h3 className="mb-4 flex items-center gap-2 font-mono text-[11px] font-semibold uppercase tracking-[0.16em] text-signal-ink">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="1.6" />
          <path d="M12 11v5M12 8h.01" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
        </svg>
        Sources
      </h3>
      <ol className="space-y-2.5">
        {sources.map((source, i) => (
          <li key={source.url} className="flex items-baseline gap-3 font-mono text-[13px]">
            <span className="flex-none text-signal-ink">{String(i + 1).padStart(2, "0")}</span>
            <a
              href={source.url}
              target="_blank"
              rel="noopener noreferrer"
              className="min-w-0 truncate text-fg underline-offset-3 transition-colors hover:text-signal hover:underline"
            >
              {source.label}
            </a>
            <span className="ml-auto flex-none text-muted" aria-hidden="true">
              ↗
            </span>
          </li>
        ))}
      </ol>
    </section>
  );
}

"use client";

import { useState } from "react";

function encode(text: string) {
  return encodeURIComponent(text);
}

/**
 * Share buttons — copy link plus X / LinkedIn / Facebook intents and a
 * native share fallback where the platform supports it.
 */
export function ShareButtons({ title, url }: { title: string; url: string }) {
  const [copied, setCopied] = useState(false);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(url);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      /* clipboard unavailable */
    }
  };

  const nativeShare = async () => {
    try {
      if (navigator.share) await navigator.share({ title, url });
    } catch {
      /* user cancelled */
    }
  };

  const links = [
    {
      label: "X",
      href: `https://twitter.com/intent/tweet?url=${encode(url)}&text=${encode(title)}`,
    },
    {
      label: "LinkedIn",
      href: `https://www.linkedin.com/sharing/share-offsite/?url=${encode(url)}`,
    },
    {
      label: "Facebook",
      href: `https://www.facebook.com/sharer/sharer.php?u=${encode(url)}`,
    },
  ];

  return (
    <div className="flex items-center gap-2" aria-label="Share this article">
      <button
        type="button"
        onClick={copy}
        className="inline-flex h-9 items-center gap-2 rounded-md border border-line bg-surface px-3 font-mono text-[11px] font-semibold uppercase tracking-[0.08em] text-fg transition-colors hover:border-signal/50"
      >
        {copied ? "✓ Copied" : "Copy link"}
      </button>
      {links.map((l) => (
        <a
          key={l.label}
          href={l.href}
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex h-9 items-center rounded-md border border-line bg-surface px-3 font-mono text-[11px] font-semibold uppercase tracking-[0.08em] text-fg transition-colors hover:border-signal/50"
        >
          {l.label}
        </a>
      ))}
      {typeof navigator !== "undefined" && navigator.share && (
        <button
          type="button"
          onClick={nativeShare}
          aria-label="Share"
          className="inline-flex h-9 w-9 items-center justify-center rounded-md border border-line bg-surface text-fg transition-colors hover:border-signal/50"
        >
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <circle cx="18" cy="5" r="3" stroke="currentColor" strokeWidth="1.7" />
            <circle cx="6" cy="12" r="3" stroke="currentColor" strokeWidth="1.7" />
            <circle cx="18" cy="19" r="3" stroke="currentColor" strokeWidth="1.7" />
            <path d="m8.6 13.5 6.8 4M15.4 6.5l-6.8 4" stroke="currentColor" strokeWidth="1.7" />
          </svg>
        </button>
      )}
    </div>
  );
}

