import type { MetadataRoute } from "next";
import { siteConfig } from "@/lib/site";
import { getAllArticles, getCategories } from "@/content";

const STATIC_ROUTES = [
  { path: "/", priority: 1 },
  { path: "/news", priority: 0.9 },
  { path: "/trending", priority: 0.9 },
  { path: "/tools", priority: 0.8 },
  { path: "/tools/word-counter", priority: 0.8 },
  { path: "/tools/character-counter", priority: 0.8 },
  { path: "/tools/meta-description-generator", priority: 0.8 },
];

export default function sitemap(): MetadataRoute.Sitemap {
  const now = new Date();

  const staticEntries: MetadataRoute.Sitemap = STATIC_ROUTES.map((r) => ({
    url: `${siteConfig.url}${r.path === "/" ? "" : r.path}`,
    lastModified: now,
    changeFrequency: r.path === "/" ? "hourly" : "weekly",
    priority: r.priority,
  }));

  const categoryEntries: MetadataRoute.Sitemap = getCategories().map((c) => ({
    url: `${siteConfig.url}/${c.slug}`,
    lastModified: now,
    changeFrequency: "daily",
    priority: 0.8,
  }));

  const articleEntries: MetadataRoute.Sitemap = getAllArticles().map((a) => ({
    url: `${siteConfig.url}/${a.category}/${a.slug}`,
    lastModified: a.updatedAt ? new Date(a.updatedAt) : new Date(a.publishedAt),
    changeFrequency: "daily",
    priority: 0.7,
  }));

  return [...staticEntries, ...categoryEntries, ...articleEntries];
}

import type { MetadataRoute } from "next";
import { siteConfig } from "@/lib/site";

export default function robots(): MetadataRoute.Robots {
  return {
    rules: [{ userAgent: "*", allow: "/", disallow: ["/admin", "/login", "/register"] }],
    sitemap: `${siteConfig.url}/sitemap.xml`,
  };
}

import Link from "next/link";
import { Breadcrumbs } from "@/components/breadcrumbs";

export function StaticPage({
  title,
  kicker = "Reference",
  children,
}: {
  title: string;
  kicker?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="mx-auto max-w-[760px] px-4 pt-8">
      <Breadcrumbs crumbs={[{ label: title }]} />
      <header className="mb-8">
        <p className="mb-1.5 font-mono text-[11px] font-semibold uppercase tracking-[0.16em] text-signal-ink">
          {kicker}
        </p>
        <h1 className="font-display text-4xl font-extrabold uppercase leading-none text-fg sm:text-5xl">
          {title}
        </h1>
      </header>
      <div className="prose-article">{children}</div>
      <p className="mt-10">
        <Link href="/" className="font-mono text-[12px] text-signal-ink hover:underline">
          ← Back to AI Tech
        </Link>
      </p>
    </div>
  );
}

import type { Metadata } from "next";
import { StaticPage } from "@/components/static-page";

export const metadata: Metadata = {
  title: "Contact",
  description: "Get in touch with the AI Tech team — tips, corrections and partnerships.",
  alternates: { canonical: "/contact" },
};

export default function ContactPage() {
  return (
