"use client";

import { useCallback, useSyncExternalStore } from "react";

function subscribeTheme(callback: () => void) {
  const observer = new MutationObserver(callback);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["class"],
  });
  window.addEventListener("storage", callback);
  return () => {
    observer.disconnect();
    window.removeEventListener("storage", callback);
  };
}

function getThemeSnapshot() {
  return document.documentElement.classList.contains("light");
}

/** Dark is the default; hydration starts from the server value (false). */
function getServerSnapshot() {
  return false;
}

/**
 * Dark is the default theme; this toggle adds/removes `.light` on <html>
 * (see globals.css). Persisted in localStorage. No flash: an inline script
 * in the root layout sets the class before paint.
 */
export function ThemeToggle() {
  const light = useSyncExternalStore(subscribeTheme, getThemeSnapshot, getServerSnapshot);

  const toggle = useCallback(() => {
    const next = !light;
    document.documentElement.classList.toggle("light", next);
    try {
      localStorage.setItem("aitech-theme", next ? "light" : "dark");
    } catch {
      /* storage unavailable — ignore */
    }
  }, [light]);

  return (
    <button
      type="button"
      onClick={toggle}
      aria-label={light ? "Switch to dark mode" : "Switch to light mode"}
      className="inline-flex h-9 w-9 items-center justify-center rounded-md border border-line bg-surface text-muted transition-colors hover:text-fg"
    >
      {light ? (
        /* moon */
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path
            d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8Z"
            stroke="currentColor"
            strokeWidth="1.8"
            strokeLinejoin="round"
          />
        </svg>
      ) : (
        /* sun */
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <circle cx="12" cy="12" r="4" stroke="currentColor" strokeWidth="1.8" />
          <path
            d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"
            stroke="currentColor"
            strokeWidth="1.8"
            strokeLinecap="round"
          />
        </svg>
      )}
    </button>
  );
}

"use client";

import { useState } from "react";

function encode(text: string) {
  return encodeURIComponent(text);
}

/**
 * Share buttons — copy link plus X / LinkedIn / Facebook intents and a
 * native share fallback where the platform supports it (falls back to
 * copying the link where navigator.share isn't available).
 */
export function ShareButtons({ title, url }: { title: string; url: string }) {
  const [copied, setCopied] = useState(false);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(url);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      /* clipboard unavailable */
    }
  };

  const share = async () => {
    if (!navigator.share) {
      await copy();
      return;
    }
    try {
      await navigator.share({ title, url });
    } catch {
      /* user cancelled */
    }
  };

  const links = [
    {
      label: "X",
      href: `https://twitter.com/intent/tweet?url=${encode(url)}&text=${encode(title)}`,
    },
    {
      label: "LinkedIn",
      href: `https://www.linkedin.com/sharing/share-offsite/?url=${encode(url)}`,
    },
    {
      label: "Facebook",
      href: `https://www.facebook.com/sharer/sharer.php?u=${encode(url)}`,
    },
  ];

  return (
    <div className="flex items-center gap-2" aria-label="Share this article">
      <button
        type="button"
        onClick={copy}
        className="inline-flex h-9 items-center gap-2 rounded-md border border-line bg-surface px-3 font-mono text-[11px] font-semibold uppercase tracking-[0.08em] text-fg transition-colors hover:border-signal/50"
      >
        {copied ? "✓ Copied" : "Copy link"}
      </button>
      {links.map((l) => (
        <a
          key={l.label}
          href={l.href}
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex h-9 items-center rounded-md border border-line bg-surface px-3 font-mono text-[11px] font-semibold uppercase tracking-[0.08em] text-fg transition-colors hover:border-signal/50"
        >
          {l.label}
        </a>
      ))}
      <button
        type="button"
        onClick={share}
        aria-label="Share"
        className="inline-flex h-9 w-9 items-center justify-center rounded-md border border-line bg-surface text-fg transition-colors hover:border-signal/50"
      >
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <circle cx="18" cy="5" r="3" stroke="currentColor" strokeWidth="1.7" />
          <circle cx="6" cy="12" r="3" stroke="currentColor" strokeWidth="1.7" />
          <circle cx="18" cy="19" r="3" stroke="currentColor" strokeWidth="1.7" />
          <path d="m8.6 13.5 6.8 4M15.4 6.5l-6.8 4" stroke="currentColor" strokeWidth="1.7" />
        </svg>
      </button>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { getCategoryBySlug } from "@/content/categories";

interface SearchIndexEntry {
  slug: string;
  title: string;
  category: string;
  excerpt: string;
}

const OPEN_EVENT = "aitech:search";

/**
 * Lightweight client-side search over a small static index passed in from
 * the header. No API call, works on fully static hosting.
 *   - The header search button dispatches `aitech:search`.
 *   - "/" opens it from anywhere; Escape closes it.
 */
export function SearchDialog({ index }: { index: SearchIndexEntry[] }) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  const openDialog = useCallback(() => {
    setQuery("");
    setOpen(true);
    requestAnimationFrame(() => inputRef.current?.focus());
  }, []);

  const closeDialog = useCallback(() => setOpen(false), []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "/" && !open && !isTyping(e.target)) {
        e.preventDefault();
        openDialog();
      }
      if (e.key === "Escape") setOpen(false);
    };
    const onOpenEvent = () => openDialog();
    window.addEventListener("keydown", onKey);
    window.addEventListener(OPEN_EVENT, onOpenEvent);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener(OPEN_EVENT, onOpenEvent);
    };
  }, [open, openDialog]);

  useEffect(() => {
    document.body.style.overflow = open ? "hidden" : "";
    return () => {
      document.body.style.overflow = "";
    };
  }, [open]);

  const results = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return [];
    return index
      .filter(
        (a) =>
          a.title.toLowerCase().includes(q) ||
          a.excerpt.toLowerCase().includes(q) ||
          a.category.toLowerCase().includes(q),
      )
      .slice(0, 8);
  }, [query, index]);

  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center bg-black/60 p-4 pt-[12vh] backdrop-blur-sm"
      onClick={closeDialog}
      role="dialog"
      aria-modal="true"
      aria-label="Search"
    >
      <div
        className="w-full max-w-xl overflow-hidden rounded-xl border border-line bg-surface shadow-card"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center gap-3 border-b border-line px-4">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true" className="text-muted">
            <circle cx="11" cy="11" r="7" stroke="currentColor" strokeWidth="1.8" />
            <path d="m20 20-3.5-3.5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
          </svg>
          <input
            ref={inputRef}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search articles, tools, categories…"
            className="h-14 w-full bg-transparent font-mono text-sm outline-none placeholder:text-muted"
          />
          <kbd className="rounded border border-line px-1.5 py-0.5 font-mono text-[10px] text-muted">ESC</kbd>
        </div>
        <ul className="scroll-slim max-h-[48vh] overflow-y-auto p-2">
          {query && results.length === 0 && (
            <li className="px-3 py-6 text-center font-mono text-xs text-muted">
              No results for “{query}”
            </li>
          )}
          {results.map((a) => {
            const cat = getCategoryBySlug(a.category as never);
            return (
              <li key={a.slug}>
                <Link
                  href={`/${a.category}/${a.slug}`}
                  onClick={closeDialog}
                  className="flex items-center gap-3 rounded-lg px-3 py-2.5 transition-colors hover:bg-surface-2"
                >
                  <span
                    className="h-1.5 w-1.5 flex-none rounded-full"
                    style={{ background: cat?.color ?? "var(--signal)" }}
                  />
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-medium text-fg">{a.title}</span>
                    <span className="block truncate font-mono text-[11px] text-muted">
                      {a.category.toUpperCase()} · {a.excerpt.slice(0, 80)}…
                    </span>
                  </span>
                </Link>
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}

function isTyping(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  const tag = target.tagName;
  return tag === "INPUT" || tag === "TEXTAREA" || target.isContentEditable;
}

