import type { Article, Author, Category } from "@/content/types";
import { aiArticles } from "@/content/articles/ai";
import { softwareArticles } from "@/content/articles/software";
import { authors as authorSeed } from "@/content/authors";
import { categories as categorySeed } from "@/content/categories";
import { affiliateCatalogs } from "@/content/affiliate";

/**
 * Content repository — the Phase 2 swap point.
 *
 * Phase 1 ships a static implementation backed by typed data files in
 * `src/content/`. Phase 2 replaces `repository` with a D1-backed
 * implementation (same interface, rows from `db/schema.sql`) so articles can
 * be managed from the admin panel without touching any template or page.
 */
export interface ContentRepository {
  getArticles(): Article[];
  getAuthors(): Author[];
  getCategories(): Category[];
  getAffiliateProducts(catalog?: string): AffiliateProductData[];
}

export interface AffiliateProductData {
  name: string;
  tagline: string;
  rating: number;
  price: string;
  bestFor: string;
  pros: string[];
  cons: string[];
  url: string;
  badge?: string;
}

export class StaticContentRepository implements ContentRepository {
  private readonly articles: Article[];
  private readonly authors: Author[];
  private readonly categories: Category[];

  constructor() {
    this.articles = [...aiArticles, ...softwareArticles];
    this.authors = authorSeed;
    this.categories = categorySeed;
  }

  getArticles(): Article[] {
    return this.articles;
  }

  getAuthors(): Author[] {
    return this.authors;
  }

  getCategories(): Category[] {
    return this.categories;
  }

  getAffiliateProducts(catalog?: string): AffiliateProductData[] {
    if (!catalog) return [];
    return affiliateCatalogs[catalog] ?? [];
  }
}

/**
 * The active repository. Phase 2: replace with:
 *   export const repository: ContentRepository = new D1ContentRepository(env);
 */
export const repository: ContentRepository = new StaticContentRepository();

import type { Article } from "./types";
import { repository } from "@/lib/db/repository";
import { getAuthor } from "./authors";
import { getCategory } from "./categories";
import { getAffiliateCatalog } from "./affiliate";

/**
 * Single access point to article content.
 *
 * All reads go through `repository` (src/lib/db/repository.ts). Phase 1 uses
 * the static implementation; Phase 2 swaps in a D1-backed one without
 * changing any page or component.
 */

const allArticles: Article[] = repository.getArticles();

export function getAllArticles(): Article[] {
  return allArticles;
}

export function getArticle(slug: string): Article | undefined {
  return allArticles.find((a) => a.slug === slug);
}

export function getArticlesByCategory(category: string): Article[] {
  return allArticles
    .filter((a) => a.category === category)
    .sort((a, b) => +new Date(b.publishedAt) - +new Date(a.publishedAt));
}

export function getLatestArticles(limit?: number): Article[] {
  const sorted = [...allArticles].sort(
    (a, b) => +new Date(b.publishedAt) - +new Date(a.publishedAt),
  );
  return limit ? sorted.slice(0, limit) : sorted;
}

export function getFeaturedArticle(): Article | undefined {
  return allArticles.find((a) => a.featured) ?? getLatestArticles(1)[0];
}

export function getTrendingArticles(): Article[] {
  return [...allArticles]
    .filter((a) => a.trendingRank != null)
    .sort((a, b) => (a.trendingRank ?? 99) - (b.trendingRank ?? 99))
    .slice(0, 6);
}

export function getRelatedArticles(article: Article, limit = 3): Article[] {
  const pool = article.related
    ?.map((slug) => getArticle(slug))
    .filter((a): a is Article => Boolean(a));
  const explicit = pool ?? [];
  const byCategory = getArticlesByCategory(article.category).filter(
    (a) => a.slug !== article.slug && !explicit.some((e) => e.slug === a.slug),
  );
  return [...explicit, ...byCategory].slice(0, limit);
}

/** Search index: lightweight title/slug/tag list used by the search dialog. */
export function getSearchIndex() {
  return allArticles.map((a) => ({
    slug: a.slug,
    title: a.title,
    category: a.category,
    excerpt: a.excerpt,
  }));
}

/** Article routes for static generation ([category]/[slug]). */
export function getAllArticleSlugs(): string[] {
  return allArticles.map((a) => a.slug);
}

export function getCategoriesWithArticles() {
  return repository
    .getCategories()
    .filter((c) => allArticles.some((a) => a.category === c.slug));
}

export function getCategories() {
  return repository.getCategories();
}

export function getAuthorBySlug(slug: string) {
  return getAuthor(slug);
}

export function getAuthors() {
  return repository.getAuthors();
}

export function getCategoryBySlugSafe(slug: string) {
  return getCategory(slug);
}

export { getCategoryBySlug, getAffiliateCatalog };

