/**
 * Auth seam — Phase 2.
 *
 * Phase 1 ships the seam and the server-side enforcement points; real
 * sessions arrive with Auth.js (or a custom cookie/session flow) backed by
 * D1. Every admin route calls `getSession()` at the server — access is
 * enforced at the auth layer, not by hiding UI.
 */

export type UserRole = "reader" | "author" | "editor" | "admin";

export interface SessionUser {
  id: string;
  email: string;
  name: string;
  role: UserRole;
}

const ADMIN_ROLES: UserRole[] = ["editor", "admin"];

/**
 * Returns the current session or null.
 * Phase 2 implementation (D1 + Auth.js):
 *   const cookieStore = await cookies();
 *   const sessionToken = cookieStore.get("authjs.session-token")?.value;
 *   if (!sessionToken) return null;
 *   // → look up sessions join users in D1, check expiry, return SessionUser.
 */
export async function getSession(): Promise<SessionUser | null> {
  return null;
}

/** Admin-gate helper. Returns the session when the user may enter, else null. */
export async function requireAdmin(): Promise<SessionUser | null> {
  const session = await getSession();
  if (!session) return null;
  if (!ADMIN_ROLES.includes(session.role)) return null;
  return session;
}

/** `true` during local development so the Phase 2 shell is previewable. */
export function isAdminPreview(): boolean {
  return process.env.AITECH_PHASE2 === "true";
}

import Link from "next/link";
import { requireAdmin, isAdminPreview } from "@/lib/db/auth";

const NAV = [
  { href: "/admin", label: "Dashboard", exact: true },
  { href: "/admin/articles", label: "Articles", exact: false },
  { href: "/admin/users", label: "Users", exact: false },
  { href: "/admin/analytics", label: "Analytics", exact: false },
];

/**
 * Admin shell. Server-side gate: no valid admin session → the layout renders
 * the gate instead of admin content. In Phase 1 the gate is on by default;
 * set AITECH_PHASE2=true locally to preview the shell.
 */
export default async function AdminLayout({ children }: { children: React.ReactNode }) {
  const session = await requireAdmin();
  const preview = isAdminPreview();

  if (!session && !preview) {
    return (
      <div className="mx-auto flex min-h-[70vh] max-w-xl flex-col items-center justify-center px-4 text-center">
        <p className="font-mono text-[11px] font-semibold uppercase tracking-[0.16em] text-amber">
          <span className="status-dot is-live" /> Access restricted
        </p>
        <h1 className="mt-3 font-display text-4xl font-extrabold uppercase leading-none text-fg">
          Admin area locked
        </h1>
        <p className="mt-4 text-sm leading-relaxed text-muted">
