import { NextResponse } from "next/server";
import { getDB } from "@/lib/db/client";
import { hashPassword, createSessionToken, sessionCookieOptions, SESSION_COOKIE } from "@/lib/db/auth";

export const dynamic = "force-dynamic";

export async function POST(req: Request) {
  let body;
  try { body = await req.json(); } catch { return json({error:"Invalid request"}, 400); }
  const name = (body.name ?? "").trim();
  const email = (body.email ?? "").trim().toLowerCase();
  const password = body.password ?? "";
  if (!name || name.length > 80) return json({error:"Name is required"}, 422);
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return json({error:"Enter a valid email"}, 422);
  if (password.length < 8) return json({error:"Password must be at least 8 characters"}, 422);

  const db = await getDB();
  const existing = await db.prepare("SELECT id FROM users WHERE email = ?").bind(email).first();
  if (existing) return json({error:"An account with this email already exists"}, 409);

  const id = crypto.randomUUID();
  const passwordHash = await hashPassword(password);
  await db.prepare("INSERT INTO users (id, email, name, password_hash, role) VALUES (?, ?, ?, ?, ?)").bind(id, email, name, passwordHash, "reader").run();

  const token = await createSessionToken({ id, name, email, role: "reader" });
  const res = NextResponse.json({ ok: true });
  res.cookies.set(SESSION_COOKIE, token, sessionCookieOptions());
  return res;
}
