 */
export function Hero({ featured, trending }: { featured: Article; trending: Article[] }) {
  const tag = getStatusTag(featured);
  const author = getAuthorBySlug(featured.author);
  const category = getCategoryBySlugSafe(featured.category);

  return (
    <section className="mx-auto max-w-[1440px] px-4 pt-6 sm:pt-8">
      <div className="grid gap-5 lg:grid-cols-[1.85fr_1fr]">
        {/* Left — featured story */}
        <Link
          href={`/${featured.category}/${featured.slug}`}
          className="group relative overflow-hidden rounded-2xl border border-line bg-surface"
        >
          <div className="relative aspect-[16/8] overflow-hidden sm:aspect-[16/7]">
            <CoverArt
              image={featured.image}
              seed={featured.slug}
              className="h-full w-full transition-transform duration-700 group-hover:scale-[1.02]"
            />
            <div className="absolute inset-x-0 bottom-0 h-2/3 bg-gradient-to-t from-black/85 via-black/40 to-transparent" />
            <div className="absolute left-4 top-4 sm:left-6 sm:top-6">
              {tag && <StatusTag tag={tag} size="lg" />}
            </div>
            {featured.sponsored && (
              <span className="absolute right-4 top-4 rounded border border-amber/50 bg-black/60 px-2 py-0.5 font-mono text-[10px] font-bold uppercase tracking-[0.16em] text-amber">
                Sponsored
              </span>
            )}
          </div>

          <div className="absolute inset-x-0 bottom-0 p-5 sm:p-8">
            <div className="mb-2 flex flex-wrap items-center gap-2 font-mono text-[11px] text-white/70">
              <span
                className="flex items-center gap-1.5 rounded border border-white/20 bg-white/10 px-2 py-0.5 font-semibold uppercase tracking-[0.12em] text-white"
                style={{ borderColor: "transparent", background: "var(--signal)" }}
              >
                {category?.name ?? "AI"}
              </span>
              <span>{author?.name ?? "AI Tech Desk"}</span>
              <span aria-hidden="true">·</span>
              <span>{relativeTime(featured.publishedAt)}</span>
              <span aria-hidden="true">·</span>
              <span>{readingMinutes(featured.content)} min read</span>
            </div>
            <h1 className="max-w-3xl font-display text-3xl font-extrabold uppercase leading-[0.95] text-white sm:text-5xl">
              {featured.title}
            </h1>
            <p className="mt-3 line-clamp-2 max-w-2xl text-sm leading-relaxed text-white/75 sm:text-base">
              {featured.excerpt}
            </p>
            <span className="mt-4 inline-flex items-center gap-2 font-mono text-[12px] font-semibold uppercase tracking-[0.14em] text-amber">
              Read the story <span className="transition-transform group-hover:translate-x-1">→</span>
            </span>
          </div>
        </Link>

        {/* Right — trending ticker */}
        <aside className="flex flex-col overflow-hidden rounded-2xl border border-line bg-surface">
          <div className="flex items-center justify-between border-b border-line px-4 py-3">
            <h2 className="flex items-center gap-2 font-mono text-[12px] font-semibold uppercase tracking-[0.14em] text-signal-ink">
              <span className="status-dot is-trending" />
              Trending now
