import Link from "next/link";
import type { Article } from "@/content/types";

/**
 * Full-width broadcast crawl. The headline set is rendered twice and the
 * track translates -50% on a loop (see `.ticker-track` in globals.css), so
 * the crawl never runs out of items. Pauses on hover; `prefers-reduced-motion`
 * falls back to a static strip.
 */
export function Ticker({ articles }: { articles: Article[] }) {
  const items = articles.slice(0, 6);
  const loop = [...items, ...items];

  return (
    <div
      role="marquee"
      aria-label="Latest headlines"
      className="flex items-stretch overflow-hidden border-b border-line bg-surface-2"
    >
      <span className="flex flex-none items-center gap-2 bg-amber px-3 py-2 font-mono text-[11px] font-bold uppercase tracking-[0.14em] text-black sm:px-4">
        <span className="inline-block h-1.5 w-1.5 rounded-full bg-black" aria-hidden="true" />
        Breaking
      </span>
      <div className="relative flex-1 overflow-hidden">
        <div className="ticker-track flex h-full items-center">
          {loop.map((article, i) => (
            <Link
              key={`${article.slug}-${i}`}
              href={`/${article.category}/${article.slug}`}
              className="flex h-full flex-none items-center gap-3 whitespace-nowrap px-5 font-mono text-[12px] uppercase tracking-[0.05em] text-muted transition-colors hover:text-fg"
            >
              <span className="text-amber" aria-hidden="true">
                ●
              </span>
              <span>{article.title}</span>
            </Link>
          ))}
        </div>
      </div>
    </div>
  );
}

import type { Article } from "@/content/types";

/**
 * Control-room readout: live pulse + editorial counts in a hairline grid.
 * `gap-px` on the container with `bg-line` shows the dividers through the
 * gap, so cells read as one dashboard strip.
 */
export function LiveStats({
  articles,
  categories,
  authors,
}: {
  articles: Article[];
  categories: number;
  authors: number;
}) {
  const latest = new Date(
    Math.max(...articles.map((a) => +new Date(a.publishedAt))),
  );
  const updated = latest.toLocaleTimeString("en", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });

  const cells = [
    {
      live: true,
      label: "Signal feed",
      value: `24/7 · updated ${updated}`,
    },
    { label: "Stories live", value: String(articles.length).padStart(2, "0") },
    { label: "Categories", value: String(categories).padStart(2, "0") },
    { label: "Desk authors", value: String(authors).padStart(2, "0") },
  ];

  return (
    <section className="mx-auto max-w-[1440px] px-4" aria-label="Live feed statistics">
      <div className="grid grid-cols-2 gap-px overflow-hidden rounded-xl border border-line bg-line sm:grid-cols-4">
        {cells.map((cell) => (
          <div
            key={cell.label}
            className={`bg-surface px-5 py-4 ${cell.live ? "col-span-2 sm:col-span-1" : ""}`}
          >
            <p
              className={`flex items-center gap-2 font-mono text-[10px] uppercase tracking-[0.16em] ${
                cell.live ? "text-amber" : "text-muted"
              }`}
            >
              {cell.live && <span className="status-dot is-live" aria-hidden="true" />}
              {cell.label}
            </p>
            <p className="mt-1.5 font-mono text-[13px] font-semibold uppercase tracking-[0.04em] text-fg">
              {cell.value}
            </p>
          </div>
        ))}
      </div>
    </section>
  );
}

