import Link from "next/link";
import { getAllArticles, getAuthorBySlug } from "@/content";
import { getStatusTag, StatusTag } from "@/components/status-tag";

export const metadata = {
  title: "Articles — AI Tech Admin",
};

export default function AdminArticlesPage() {
  const articles = getAllArticles();

  return (
    <div>
      <header className="mb-6 flex items-end justify-between gap-4">
        <div>
          <p className="font-mono text-[10px] font-semibold uppercase tracking-[0.16em] text-muted">Editorial</p>
          <h2 className="mt-1 font-display text-3xl font-extrabold uppercase leading-none text-fg">
            Articles
          </h2>
        </div>
        <button
          type="button"
          title="Article creation arrives with Phase 2 (D1 write path)"
          className="cursor-not-allowed rounded-md border border-dashed border-line px-4 py-2 font-mono text-[12px] uppercase tracking-[0.1em] text-muted"
        >
          + New (Phase 2)
        </button>
      </header>

      <div className="overflow-x-auto rounded-lg border border-line">
        <table className="w-full min-w-[640px] text-left text-sm">
          <thead>
            <tr className="border-b border-line bg-surface-2 font-mono text-[10px] uppercase tracking-[0.12em] text-muted">
              <th className="px-4 py-3">Title</th>
              <th className="px-4 py-3">Category</th>
              <th className="px-4 py-3">Author</th>
              <th className="px-4 py-3">Status</th>
              <th className="px-4 py-3">Date</th>
              <th className="px-4 py-3 text-right">Views</th>
            </tr>
          </thead>
          <tbody>
            {articles.map((a) => {
              const author = getAuthorBySlug(a.author);
              return (
                <tr key={a.slug} className="border-b border-line last:border-0">
                  <td className="px-4 py-3">
                    <Link href={`/${a.category}/${a.slug}`} className="font-medium text-fg hover:text-signal">
                      {a.title}
                    </Link>
                  </td>
                  <td className="px-4 py-3 font-mono text-[12px] uppercase text-muted">{a.category}</td>
                  <td className="px-4 py-3 font-mono text-[12px] text-muted">{author?.name ?? "—"}</td>
                  <td className="px-4 py-3">
                    {(() => {
                      const tag = getStatusTag(a);
                      return tag ? (
                        <StatusTag tag={tag} />
                      ) : (
                        <span className="font-mono text-[11px] uppercase tracking-wider text-muted">published</span>
                      );
                    })()}
                  </td>
                  <td className="px-4 py-3 font-mono text-[12px] text-muted">
                    {new Date(a.publishedAt).toLocaleDateString("en", { year: "numeric", month: "short", day: "numeric" })}
                  </td>
                  <td className="px-4 py-3 text-right font-mono text-[12px] text-muted">—</td>
                </tr>
              );
            })}
            {articles.length === 0 && (
              <tr>
                <td colSpan={6} className="px-4 py-10 text-center font-mono text-[12px] text-muted">
                  No articles yet.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

