  return NextResponse.json(body, { status });
}

function slugify(input: string): string {
  return input
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
}

/** Lightweight markdown-lite: ## headings, - lists, > quotes, paragraphs. */
function parseBody(body: string): ContentBlock[] {
  const lines = body.split(/\r?\n/);
  const blocks: ContentBlock[] = [];
  let para: string[] = [];
  let list: string[] = [];

  const flushPara = () => {
    if (para.length) {
      blocks.push({ type: "p", text: para.join(" ").trim() });
      para = [];
    }
  };
  const flushList = () => {
    if (list.length) {
      blocks.push({ type: "list", items: list.map((l) => l.trim()) });
      list = [];
    }
  };

  for (const raw of lines) {
    const line = raw.trimEnd();
    if (line.trim() === "") {
      flushPara();
      flushList();
      continue;
    }
    if (line.startsWith("### ")) {
      flushPara(); flushList();
      blocks.push({ type: "h3", text: line.slice(4).trim() });
      continue;
    }
    if (line.startsWith("## ")) {
      flushPara(); flushList();
      blocks.push({ type: "h2", text: line.slice(3).trim() });
      continue;
    }
    if (line.startsWith("> ")) {
      flushPara(); flushList();
      blocks.push({ type: "quote", text: line.slice(2).trim() });
      continue;
    }
    if (/^[-*]\s+/.test(line)) {
      flushPara();
      list.push(line.replace(/^[-*]\s+/, ""));
      continue;
    }
    flushList();
    para.push(line.trim());
  }
  flushPara();
  flushList();
  if (blocks.length === 0) blocks.push({ type: "p", text: body.trim() });
  return blocks;
}

export async function POST(request: Request) {
  const session = await requireAdmin();
  if (!session) return json({ error: "Unauthorized." }, 401);

  let body: Record<string, unknown>;
  try {
    body = (await request.json()) as Record<string, unknown>;
  } catch {
    return json({ error: "Invalid request body." }, 400);
  }

  const title = typeof body.title === "string" ? body.title.trim() : "";
  const category = typeof body.category === "string" ? (body.category as CategorySlug) : "";
  const excerpt = typeof body.excerpt === "string" ? body.excerpt.trim() : "";
  const contentText = typeof body.content === "string" ? body.content.trim() : "";
  const tagsRaw = typeof body.tags === "string" ? body.tags : "";
  const imageDataUrl = typeof body.imageDataUrl === "string" ? body.imageDataUrl.trim() : "";
  const imageAlt = typeof body.imageAlt === "string" ? body.imageAlt.trim() : "";
  const publish = body.publish === true;

  if (!title || !category || !contentText) {
    return json({ error: "Title, category and content are required." }, 422);
  }
  if (!CATEGORIES.includes(category)) {
    return json({ error: "Unknown category." }, 422);
  }
  if (imageDataUrl && imageDataUrl.length > MAX_IMAGE_BYTES) {
    return json({ error: "Image is too large (max ~2 MB)." }, 422);
  }

  // Unique slug
  let slug = slugify(title) || "article";
  let candidate = slug;
  let n = 2;
  while ((await getDbArticle(candidate)) || getArticle(candidate)) {
    candidate = `${slug}-${n++}`;
  }
  slug = candidate;

  const tags = tagsRaw
    .split(",")
    .map((t) => t.trim().toLowerCase().replace(/\s+/g, "-"))
    .filter(Boolean)
    .slice(0, 6);

  const now = new Date().toISOString();
  const id = randomUUID();

  const image = imageDataUrl.startsWith("data:image/")
    ? { cover: category, alt: imageAlt || title, src: imageDataUrl }
    : { cover: category, alt: imageAlt || title };

  await (await getDB())
    .prepare(
      `INSERT INTO articles
        (id, slug, title, excerpt, category_slug, author_slug, status, status_tag,
         is_featured, sponsored, affiliate_disclosed, content_json, sources_json,
         image_json, seo_title, seo_description, tags_csv, published_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, 0, 0, ?, '[]', ?, ?, ?, ?, ?, ?)`,
    )
    .bind(
      id,
      slug,
      title,
      excerpt,
      category,
      "maya-kovac",
      publish ? "published" : "draft",
      publish ? "breaking" : null,
      JSON.stringify(parseBody(contentText)),
      JSON.stringify(image),
      title,
      excerpt,
      tags.join(","),
      publish ? now : now,
      now,
    )
    .run();

  return json({ ok: true, slug });
}

"use client";

import { useRef, useState } from "react";
import { useRouter } from "next/navigation";

const CATEGORIES = [
  { value: "ai", label: "AI" },
  { value: "software", label: "Software" },
  { value: "security", label: "Cybersecurity" },
  { value: "gadgets", label: "Gadgets" },
  { value: "cloud", label: "Cloud & Hosting" },
  { value: "reviews", label: "Reviews" },
  { value: "guides", label: "How-To Guides" },
];

const inputCls =
  "w-full rounded-md border border-line bg-surface px-3 py-2 text-sm text-fg placeholder:text-muted/60 focus:border-signal/60 focus:outline-none";
const labelCls = "mb-1.5 block font-mono text-[10px] uppercase tracking-[0.14em] text-muted";

export function ArticleForm() {
  const router = useRouter();
  const fileRef = useRef<HTMLInputElement>(null);
  const [title, setTitle] = useState("");
  const [category, setCategory] = useState("ai");
  const [excerpt, setExcerpt] = useState("");
  const [tags, setTags] = useState("");
  const [content, setContent] = useState("");
  const [imageAlt, setImageAlt] = useState("");
  const [preview, setPreview] = useState<string | null>(null);
  const [publish, setPublish] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  function onFile(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 2 * 1024 * 1024) {
      setError("Image is too large — max ~2 MB.");
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      const data = reader.result as string;
      setPreview(data);
      if (!imageAlt) setImageAlt(title || file.name);
    };
    reader.readAsDataURL(file);
  }

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setSaving(true);
    try {
      const res = await fetch("/api/admin/articles", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title,
          category,
          excerpt,
          tags,
          content,
          imageDataUrl: preview,
          imageAlt,
          publish,
        }),
      });
      const data = await res.json();
      if (!res.ok || !data.ok) {
        setError(data.error ?? "Failed to create article.");
        setSaving(false);
        return;
      }
      router.push(publish ? `/${category}/${data.slug}` : "/admin/articles");
      router.refresh();
    } catch {
      setError("Network error — please try again.");
      setSaving(false);
    }
  }

  return (
    <form onSubmit={onSubmit} className="space-y-5">
      <div className="grid gap-5 md:grid-cols-2">
        <div className="md:col-span-2">
          <label className={labelCls} htmlFor="art-title">Title</label>
          <input
            id="art-title"
            className={inputCls}
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="e.g. Anthropic Ships Claude Next"
            required
          />
        </div>

        <div>
          <label className={labelCls} htmlFor="art-category">Category</label>
          <select
            id="art-category"
            className={inputCls}
            value={category}
            onChange={(e) => setCategory(e.target.value)}
          >
            {CATEGORIES.map((c) => (
              <option key={c.value} value={c.value}>
                {c.label}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className={labelCls} htmlFor="art-tags">Tags (comma separated)</label>
          <input
            id="art-tags"
            className={inputCls}
            value={tags}
            onChange={(e) => setTags(e.target.value)}
            placeholder="ai, models, launch"
          />
        </div>

        <div className="md:col-span-2">
          <label className={labelCls} htmlFor="art-excerpt">Excerpt / summary</label>
          <textarea
            id="art-excerpt"
            className={`${inputCls} resize-y`}
            rows={2}
            value={excerpt}
            onChange={(e) => setExcerpt(e.target.value)}
            placeholder="One or two sentences shown in cards and search."
          />
        </div>

        <div className="md:col-span-2">
          <label className={labelCls} htmlFor="art-content">Body</label>
          <textarea
            id="art-content"
            className={`${inputCls} resize-y font-mono text-[13px] leading-relaxed`}
            rows={14}
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder={"Write the article here.\n\nUse ## for headings, - for lists, > for quotes.\n\nSeparate paragraphs with a blank line."}
            required
          />
        </div>

        <div className="md:col-span-2">
          <label className={labelCls}>Cover image</label>
          <div className="flex flex-wrap items-center gap-4">
            <input
              ref={fileRef}
              type="file"
              accept="image/png,image/jpeg,image/webp,image/gif,image/svg+xml"
              className="hidden"
              onChange={onFile}
            />
            <button
              type="button"
              onClick={() => fileRef.current?.click()}
              className="rounded-md border border-line bg-surface px-4 py-2 font-mono text-[12px] uppercase tracking-[0.1em] text-muted transition-colors hover:text-fg"
            >
              {preview ? "Replace image" : "Upload image"}
            </button>
            {preview && (
              // eslint-disable-next-line @next/next/no-img-element
              <img src={preview} alt="Cover preview" className="h-20 w-32 rounded-md border border-line object-cover" />
            )}
            {!preview && (
              <span className="font-mono text-[11px] text-muted">
                Optional — leave empty for an auto-generated cover.
              </span>
            )}
          </div>
        </div>

        <div>
          <label className={labelCls} htmlFor="art-alt">Image alt text</label>
          <input
            id="art-alt"
            className={inputCls}
            value={imageAlt}
            onChange={(e) => setImageAlt(e.target.value)}
            placeholder="Describe the image"
          />
        </div>

        <label className="flex cursor-pointer items-center gap-3 rounded-md border border-line bg-surface px-4 py-3">
          <input
            type="checkbox"
            checked={publish}
            onChange={(e) => setPublish(e.target.checked)}
            className="h-4 w-4 accent-[var(--signal)]"
          />
          <span>
            <span className="block text-sm font-medium text-fg">Publish immediately</span>
            <span className="block font-mono text-[11px] text-muted">
              Published articles appear live with a BREAKING tag on top.
            </span>
          </span>
        </label>
      </div>

      {error && (
        <p className="rounded-md border border-danger/40 bg-danger/10 px-3 py-2 font-mono text-[12px] text-danger">
          {error}
        </p>
      )}

      <div className="flex items-center gap-3">
        <button
          type="submit"
          disabled={saving}
          className="rounded-md bg-signal px-5 py-2.5 font-mono text-[12px] font-semibold uppercase tracking-[0.1em] text-white transition-opacity hover:opacity-90 disabled:opacity-50"
        >
          {saving ? "Saving…" : publish ? "Publish article" : "Save draft"}
        </button>
        <span className="font-mono text-[11px] text-muted">
          {publish ? "Status will be set to BREAKING." : "Drafts stay hidden from the site."}
        </span>
      </div>
    </form>
  );
}

