import Link from "next/link";
import { NAV_LINKS } from "@/lib/site";
import { getFeaturedArticle, getSearchIndex } from "@/content";
import { relativeTime } from "@/lib/format";
import { SearchDialog } from "./search-dialog";
import { SearchTrigger } from "./search-trigger";
import { LanguageSelector } from "./language-selector";
import { ThemeToggle } from "./theme-toggle";
import { MobileNav } from "./mobile-nav";

function Logo() {
  return (
    <Link href="/" className="flex items-center gap-2" aria-label="AI Tech — home">
      <span className="relative flex h-5 w-5 items-center justify-center rounded-sm bg-signal">
        <span className="h-2 w-2 rounded-[2px] border-2 border-white" />
        <span className="absolute -right-0.5 -top-0.5 h-1.5 w-1.5 rounded-full bg-amber" />
      </span>
      <span className="font-display text-[1.35rem] font-extrabold tracking-tight text-fg">
        AI<span className="text-signal">TECH</span>
      </span>
    </Link>
  );
}

export function Header() {
  const featured = getFeaturedArticle();
  const searchIndex = getSearchIndex();

  return (
    <header className="sticky top-0 z-40">
      {/* Breaking strip */}
      {featured && (
        <div className="border-b border-line bg-surface">
          <div className="mx-auto flex h-8 max-w-[1440px] items-center gap-3 px-4">
            <span className="inline-flex flex-none items-center gap-1.5 font-mono text-[10px] font-bold uppercase tracking-[0.16em] text-amber">
              <span className="status-dot is-live" /> Breaking
            </span>
            <Link
              href={`/${featured.category}/${featured.slug}`}
              className="min-w-0 flex-1 truncate text-xs font-medium text-fg hover:text-signal"
            >
              {featured.title}
            </Link>
            <span className="hidden flex-none font-mono text-[10px] text-muted sm:block">
              {relativeTime(featured.publishedAt)}
            </span>
          </div>
        </div>
      )}

      {/* Main bar */}
      <div className="border-b border-line bg-bg/85 backdrop-blur-md">
        <div className="mx-auto flex h-16 max-w-[1440px] items-center gap-5 px-4">
          <Logo />

          <nav className="hidden items-center gap-5 xl:flex" aria-label="Primary">
            {NAV_LINKS.map((link) => (
              <Link
                key={link.href}
                href={link.href}
                className="whitespace-nowrap font-mono text-[12px] uppercase tracking-[0.08em] text-muted transition-colors hover:text-fg"
              >
                {link.label}
              </Link>
            ))}
          </nav>

          <div className="ml-auto flex items-center gap-2">
            <SearchTrigger />
            <div className="hidden sm:block">
              <LanguageSelector />
            </div>
            <div className="hidden lg:block">
              <ThemeToggle />
            </div>
            <div className="hidden items-center gap-4 lg:flex">
              <Link
                href="/login"
                className="font-mono text-[12px] uppercase tracking-[0.08em] text-muted transition-colors hover:text-fg"
              >
                Login
              </Link>
              <Link
                href="/register"
                className="rounded-md bg-signal px-3.5 py-2 font-mono text-[12px] font-semibold uppercase tracking-[0.08em] text-white transition-opacity hover:opacity-90"
              >
                Register
              </Link>
            </div>
            <div className="xl:hidden">
              <MobileNav />
            </div>
          </div>
        </div>
      </div>

      {/* Floating search dialog (lazy, no-op when closed) */}
      <SearchDialog index={searchIndex} />
    </header>
  );
}

