import type { Metadata } from "next";
import Link from "next/link";
import {
  getSiteLatest,
  getSiteTrending,
  getSiteCategoriesWithArticles,
  getSiteBreaking,
  getSiteFeatured,
  getAllArticles,
  getCategories,
  getAuthors,
} from "@/content";
import { Hero } from "@/components/hero";
import { Ticker } from "@/components/ticker";
import { LiveStats } from "@/components/live-stats";
import { ArticleCard } from "@/components/article-card";
import { SectionHeading } from "@/components/section-heading";
import { CategoryPreview } from "@/components/category-preview";
import { CircuitDivider } from "@/components/circuit-divider";
import { AdSlot } from "@/components/ad-slot";
import { Newsletter } from "@/components/newsletter";

export const metadata: Metadata = {
  title: {
    absolute: "AI Tech — AI & Technology News, Reviews and Free Tools",
  },
  description:
    "Live AI and technology news, hands-on software reviews, best-of comparisons and free developer tools — from the control room of the tech news cycle.",
  alternates: { canonical: "/" },
};

export const dynamic = "force-dynamic";

export default async function HomePage() {
  const breaking = await getSiteBreaking();
  const featured = breaking ?? (await getSiteFeatured());
  const trending = await getSiteTrending();
  const latest = (await getSiteLatest(9)).filter((a) => a.slug !== featured?.slug);
  const categories = await getSiteCategoriesWithArticles();

  if (!featured) return null;

  return (
    <>
      <Ticker articles={await getSiteLatest(6)} />
      <Hero featured={featured} trending={trending} />

      <div className="mt-5">
        <LiveStats
          articles={getAllArticles()}
          categories={getCategories().length}
          authors={getAuthors().length}
        />
      </div>

      {/* Latest news grid */}
      <section className="mx-auto mt-12 max-w-[1440px] px-4">
        <SectionHeading
          kicker="The news cycle"
          title="Latest News"
          href="/news"
          linkLabel="All articles"
        />
        <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
          {latest.map((article) => (
            <ArticleCard key={article.slug} article={article} />
          ))}
        </div>
      </section>

      <div className="mx-auto max-w-[1440px] px-4">
        <AdSlot slot="home-mid" />
      </div>

      {/* Trending strip */}
      <section className="mx-auto max-w-[1440px] px-4">
        <SectionHeading
          kicker="Most read right now"
          title="Trending"
          href="/trending"
          linkLabel="See rankings"
        />
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {trending.map((article, i) => (
            <Link
              key={article.slug}
              href={`/${article.category}/${article.slug}`}
              className="group relative flex flex-col overflow-hidden rounded-xl border border-line bg-surface p-4 transition-colors hover:border-signal/40"
            >
              <span className="font-display text-5xl font-extrabold text-line transition-colors group-hover:text-signal">
                {String(i + 1).padStart(2, "0")}
              </span>
              <h3 className="mt-3 line-clamp-3 font-display text-lg font-bold uppercase leading-none text-fg group-hover:text-signal-ink">
                {article.title}
              </h3>
              <p className="mt-2 font-mono text-[10px] uppercase tracking-wider text-muted">
                {article.category} · {new Date(article.publishedAt).toLocaleDateString("en", { month: "short", day: "numeric" })}
              </p>
            </Link>
          ))}
        </div>
      </section>

      <div className="mx-auto max-w-[1440px] px-4">
        <CircuitDivider className="mt-10" />
      </div>

      {/* Category preview rows */}
      <div className="mt-10 space-y-12">
        {categories.map((category) => (
          <CategoryPreview key={category.slug} category={category} />
        ))}
      </div>

      {/* Newsletter */}
      <section className="mx-auto mt-12 max-w-[1440px] px-4">
        <div className="relative overflow-hidden rounded-2xl border border-line bg-surface p-8 sm:p-12">
          <div className="circuit-trace pointer-events-none absolute inset-0 opacity-40" aria-hidden="true" />
          <div className="relative mx-auto max-w-2xl text-center">
            <p className="mb-2 inline-flex items-center gap-2 font-mono text-[11px] font-semibold uppercase tracking-[0.16em] text-signal-ink">
              <span className="status-dot is-live" /> The Signal
            </p>
            <h2 className="font-display text-3xl font-extrabold uppercase leading-none text-fg sm:text-4xl">
              Get the Signal in your inbox
            </h2>
            <p className="mx-auto mt-3 max-w-md text-sm leading-relaxed text-muted">
              One email, every weekday. The AI and tech news that actually matters —
              no fluff, five minutes.
            </p>
            <div className="mx-auto mt-6 max-w-md">
              <Newsletter />
            </div>
            <p className="mt-3 font-mono text-[10px] text-muted">
              No spam. Unsubscribe anytime.
            </p>
          </div>
        </div>
      </section>

      <div className="mx-auto max-w-[1440px] px-4">
        <AdSlot slot="home-bottom" />
      </div>
    </>
  );
}

