import type { Metadata, Viewport } from "next";
import { Big_Shoulders, IBM_Plex_Mono, Inter } from "next/font/google";
import "./globals.css";
import { siteConfig } from "@/lib/site";
import { Header } from "@/components/header";
import { Footer } from "@/components/footer";

const display = Big_Shoulders({
  variable: "--font-display",
  subsets: ["latin"],
  display: "swap",
});

const sans = Inter({
  variable: "--font-sans",
  subsets: ["latin"],
  display: "swap",
});

const mono = IBM_Plex_Mono({
  variable: "--font-mono",
  subsets: ["latin"],
  weight: ["400", "500", "600", "700"],
  display: "swap",
});

export const metadata: Metadata = {
  metadataBase: new URL(siteConfig.url),
  title: {
    default: siteConfig.name,
    template: `%s — ${siteConfig.name}`,
  },
  description:
    "AI, software, cybersecurity and cloud news, reviews and free developer tools. Live coverage of the technology news cycle.",
  keywords: [
    "AI news",
    "artificial intelligence",
    "software",
    "cybersecurity",
    "tech reviews",
    "free SEO tools",
    "AI tools",
  ],
  openGraph: {
    type: "website",
    locale: siteConfig.locale,
    url: siteConfig.url,
    siteName: siteConfig.name,
    title: `${siteConfig.name} — AI & Technology News`,
    description:
      "AI, software, cybersecurity and cloud news, reviews and free developer tools.",
  },
  twitter: {
    card: "summary_large_image",
    title: `${siteConfig.name} — AI & Technology News`,
    description:
      "AI, software, cybersecurity and cloud news, reviews and free developer tools.",
  },
  robots: {
    index: true,
    follow: true,
  },
  alternates: {
    canonical: "/",
  },
};

export const viewport: Viewport = {
  themeColor: "#12131C",
  colorScheme: "dark",
  width: "device-width",
  initialScale: 1,
};

const THEME_SCRIPT = `(function(){try{var t=localStorage.getItem("aitech-theme");if(t==="light")document.documentElement.classList.add("light")}catch(e){}})();`;

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html
      lang={siteConfig.locale}
      className={`${display.variable} ${sans.variable} ${mono.variable} h-full antialiased`}
      suppressHydrationWarning
    >
      <head>
        <script dangerouslySetInnerHTML={{ __html: THEME_SCRIPT }} />
      </head>
      <body className="flex min-h-full flex-col bg-bg font-sans text-fg">
        <Header />
        <main className="flex-1">{children}</main>
        <Footer />
      </body>
    </html>
  );
}

