display.text:
"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { getCategoryBySlug } from "@/content/categories";

interface SearchIndexEntry {
  slug: string;
  title: string;
  category: string;
  excerpt: string;
}

const OPEN_EVENT = "aitech:search";

/**
 * Lightweight client-side search over a small static index passed in from
 * the header. No API call, works on fully static hosting.
 *   - The header search button dispatches `aitech:search`.
 *   - "/" opens it from anywhere; Escape closes it.
 */
export function SearchDialog({ index }: { index: SearchIndexEntry[] }) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  const openDialog = useCallback(() => {
    setQuery("");
    setOpen(true);
    requestAnimationFrame(() => inputRef.current?.focus());
  }, []);

  const closeDialog = useCallback(() => setOpen(false), []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "/" && !open && !isTyping(e.target)) {
        e.preventDefault();
        openDialog();
      }
      if (e.key === "Escape") setOpen(false);
    };
    const onOpenEvent = () => openDialog();
    window.addEventListener("keydown", onKey);
    window.addEventListener(OPEN_EVENT, onOpenEvent);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener(OPEN_EVENT, onOpenEvent);
    };
  }, [open, openDialog]);

  useEffect(() => {
    document.body.style.overflow = open ? "hidden" : "";
    return () => {
      document.body.style.overflow = "";
    };
  }, [open]);

  const results = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return [];
    return index
      .filter(
        (a) =>
          a.title.toLowerCase().includes(q) ||
          a.excerpt.toLowerCase().includes(q) ||
          a.category.toLowerCase().includes(q),
      )
      .slice(0, 8);
  }, [query, index]);

  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center bg-black/60 p-4 pt-[12vh] backdrop-blur-sm"
      onClick={closeDialog}
      role="dialog"
      aria-modal="true"
      aria-label="Search"
    >
      <div
        className="w-full max-w-xl overflow-hidden rounded-xl border border-line bg-surface shadow-card"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center gap-3 border-b border-line px-4">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true" className="text-muted">
            <circle cx="11" cy="11" r="7" stroke="currentColor" strokeWidth="1.8" />
            <path d="m20 20-3.5-3.5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
          </svg>
          <input
            ref={inputRef}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search articles, tools, categories…"
            className="h-14 w-full bg-transparent font-mono text-sm outline-none placeholder:text-muted"
          />
          <kbd className="rounded border border-line px-1.5 py-0.5 font-mono text-[10px] text-muted">ESC</kbd>
        </div>
        <ul className="scroll-slim max-h-[48vh] overflow-y-auto p-2">
          {query && results.length === 0 && (
            <li className="px-3 py-6 text-center font-mono text-xs text-muted">
              No results for “{query}”
            </li>
          )}
          {results.map((a) => {
            const cat = getCategoryBySlug(a.category as never);
            return (
              <li key={a.slug}>
                <Link
                  href={`/${a.category}/${a.slug}`}
                  onClick={closeDialog}
                  className="flex items-center gap-3 rounded-lg px-3 py-2.5 transition-colors hover:bg-surface-2"
                >
                  <span
                    className="h-1.5 w-1.5 flex-none rounded-full"
                    style={{ background: cat?.color ?? "var(--signal)" }}
                  />
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-medium text-fg">{a.title}</span>
                    <span className="block truncate font-mono text-[11px] text-muted">
                      {a.category.toUpperCase()} · {a.excerpt.slice(0, 80)}…
                    </span>
                  </span>
                </Link>
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}

function isTyping(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  const tag = target.tagName;
  return tag === "INPUT" || tag === "TEXTAREA" || target.isContentEditable;
}

import Image from "next/image";
import type { ArticleImage } from "@/content/types";

/**
 * Deterministic, dependency-free cover art.
 *
 * Renders an abstract "broadcast still" — navy control-room background,
 * right-angle PCB circuit traces and a category accent — seeded from the
 * article slug so it never changes between deploys. No external images,
 * no image-optimization pipeline, crisp at any size.
 */

const TONES: Record<string, { accent: string; label: string }> = {
  windows: { accent: "#3B5BFF", label: "WINDOWS" },
  macos: { accent: "#5B8DEF", label: "MACOS" },
  hardware: { accent: "#FF7A59", label: "HARDWARE" },
  software: { accent: "#7C5CFF", label: "SOFTWARE" },
  internet: { accent: "#3BB4FF", label: "INTERNET" },
  security: { accent: "#2FBF8F", label: "SECURITY" },
  coding: { accent: "#FFB020", label: "CODING" },
  ai: { accent: "#FF5CA8", label: "AI & AUTO" },
  live: { accent: "#FFB020", label: "LIVE" },
  generic: { accent: "#3B5BFF", label: "TECHHOW" },
};

/** Mulberry32 — tiny deterministic PRNG so art is stable per seed. */
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hashString(str: string): number {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function Traces({ seed, accent }: { seed: string; accent: string }) {
  const rnd = mulberry32(hashString(seed) ^ 0x9e3779b9);
  const traces: React.ReactNode[] = [];
  const W = 1200;
  const H = 630;
  for (let i = 0; i < 9; i++) {
    const startX = Math.round(rnd() * W);
    const startY = Math.round(rnd() * H);
    const segments = 2 + Math.floor(rnd() * 3);
    let x = startX;
    let y = startY;
    let d = `M${x} ${y}`;
    for (let s = 0; s < segments; s++) {
      if (rnd() > 0.5) {
        x += Math.round((rnd() - 0.2) * 260);
      } else {
        y += Math.round((rnd() - 0.2) * 260);
      }
      d += ` L${Math.max(0, Math.min(W, x))} ${Math.max(0, Math.min(H, y))}`;
    }
    traces.push(
      <g key={i}>
        <path d={d} fill="none" stroke={accent} strokeOpacity={0.16} strokeWidth={2} />
        <circle cx={Math.max(0, Math.min(W, x))} cy={Math.max(0, Math.min(H, y))} r={5} fill={accent} fillOpacity={0.35} />
      </g>,
    );
  }
  return <>{traces}</>;
}

export function CoverArt({
  image,
  seed,
  className,
}: {
  image: ArticleImage;
  seed: string;
  className?: string;
}) {
  // Bundled static cover (public/images/articles/<slug>.svg) wins over the
  // generated fallback art. These are tiny already-optimized SVGs, so the
  // Next.js image optimizer is skipped via `unoptimized`.
  if (image.src) {
    return (
      <Image
        src={image.src}
        alt={image.alt}
        width={1200}
        height={630}
        unoptimized
        loading="lazy"
        decoding="async"
        style={{ objectFit: "cover", width: "100%", height: "100%" }}
        className={className}
      />
    );
  }

  const tone = TONES[image.cover] ?? TONES.generic;
  return (
    <svg
      viewBox="0 0 1200 630"
      role="img"
      aria-label={image.alt}
      className={className}
      preserveAspectRatio="xMidYMid slice"
    >
      <defs>
        <linearGradient id={`bg-${seed}`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#12131C" />
          <stop offset="100%" stopColor="#1A1D2E" />
        </linearGradient>
        <radialGradient id={`glow-${seed}`} cx="72%" cy="22%" r="80%">
          <stop offset="0%" stopColor={tone.accent} stopOpacity="0.28" />
          <stop offset="100%" stopColor={tone.accent} stopOpacity="0" />
        </radialGradient>
        <pattern id={`grid-${seed}`} width="44" height="44" patternUnits="userSpaceOnUse">
          <path d="M44 0H0V44" fill="none" stroke="#8891A6" strokeOpacity="0.12" strokeWidth="1" />
        </pattern>
      </defs>

      <rect width="1200" height="630" fill={`url(#bg-${seed})`} />
      <rect width="1200" height="630" fill={`url(#glow-${seed})`} />
      <rect width="1200" height="630" fill={`url(#grid-${seed})`} />
      <Traces seed={seed} accent={tone.accent} />

      {/* accent bars */}
      <rect x="0" y="0" width="1200" height="6" fill={tone.accent} />
      <rect x="86" y="470" width="14" height="120" fill={tone.accent} opacity="0.9" />
      <rect x="108" y="500" width="6" height="90" fill={tone.accent} opacity="0.45" />

      {/* signal block */}
      <rect x="86" y="60" width="10" height="10" fill={tone.accent} />
      <rect x="104" y="78" width="6" height="6" fill={tone.accent} opacity="0.5" />

      {/* label */}
      <text
        x="86"
        y="566"
        fontFamily="IBM Plex Mono, monospace"
        fontSize="30"
        letterSpacing="10"
        fill="#8891A6"
      >
        {tone.label}
      </text>
      <text
        x="86"
        y="438"
        fontFamily="'Big Shoulders Display', sans-serif"
        fontSize="120"
        fontWeight="800"
        fill="#F2F3F7"
        opacity="0.9"
      >
        TECHHOW
      </text>
    </svg>
  );
}

