"use client";

import { useCallback, useSyncExternalStore } from "react";

function subscribeTheme(callback: () => void) {
  const observer = new MutationObserver(callback);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["class"],
  });
  window.addEventListener("storage", callback);
  return () => {
    observer.disconnect();
    window.removeEventListener("storage", callback);
  };
}

function getThemeSnapshot() {
  return document.documentElement.classList.contains("dark");
}

/** Light is the default; hydration starts from the server value (false). */
function getServerSnapshot() {
  return false;
}

/**
 * Light is the default theme; this toggle adds/removes `.dark` on <html>
 * (see globals.css). Persisted in localStorage. No flash: an inline script
 * in the root layout sets the class before paint.
 */
export function ThemeToggle() {
  const dark = useSyncExternalStore(subscribeTheme, getThemeSnapshot, getServerSnapshot);

  const toggle = useCallback(() => {
    const next = !dark;
    document.documentElement.classList.toggle("dark", next);
    try {
      localStorage.setItem("aitech-theme", next ? "dark" : "light");
    } catch {
      /* storage unavailable — ignore */
    }
  }, [dark]);

  return (
    <button
      type="button"
      onClick={toggle}
      aria-label={dark ? "Switch to light mode" : "Switch to dark mode"}
      className="inline-flex h-9 w-9 items-center justify-center rounded-md border border-line bg-surface text-muted transition-colors hover:text-fg"
    >
      {dark ? (
        /* sun */
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <circle cx="12" cy="12" r="4" stroke="currentColor" strokeWidth="1.8" />
          <path
            d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"
            stroke="currentColor"
            strokeWidth="1.8"
            strokeLinecap="round"
          />
        </svg>
      ) : (
        /* moon */
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path
            d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8Z"
            stroke="currentColor"
            strokeWidth="1.8"
            strokeLinejoin="round"
          />
        </svg>
      )}
    </button>
  );
}

import Image from "next/image";
import type { ArticleImage } from "@/content/types";

/**
 * Deterministic, dependency-free cover art.
 *
 * Renders a clean, light abstract "editorial still" — soft gradient
 * background tinted by the category accent, a faint grid and a few
 * geometric accents — seeded from the article slug so it never changes
 * between deploys. No external images, crisp at any size.
 */

const TONES: Record<string, { accent: string; label: string }> = {
  windows: { accent: "#3b5bff", label: "WINDOWS" },
  macos: { accent: "#5b8def", label: "MACOS" },
  hardware: { accent: "#ff7a59", label: "HARDWARE" },
  software: { accent: "#7c5cff", label: "SOFTWARE" },
  internet: { accent: "#2ba8f0", label: "INTERNET" },
  security: { accent: "#17a673", label: "SECURITY" },
  coding: { accent: "#f59e0b", label: "CODING" },
  ai: { accent: "#e85bb0", label: "AI & AUTO" },
  live: { accent: "#f59e0b", label: "LIVE" },
  generic: { accent: "#4f46e5", label: "TECHHOW" },
};

/** Mulberry32 — tiny deterministic PRNG so art is stable per seed. */
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hashString(str: string): number {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function Accents({ seed, accent }: { seed: string; accent: string }) {
  const rnd = mulberry32(hashString(seed) ^ 0x9e3779b9);
  const shapes: React.ReactNode[] = [];
  const W = 1200;
  const H = 630;
  for (let i = 0; i < 7; i++) {
    const x = Math.round(rnd() * W);
    const y = Math.round(rnd() * H);
    const s = 22 + Math.round(rnd() * 60);
    const kind = i % 3;
    if (kind === 0) {
      shapes.push(
        <circle key={i} cx={x} cy={y} r={s / 2} fill="none" stroke={accent} strokeOpacity={0.18} strokeWidth={2} />,
      );
    } else if (kind === 1) {
      shapes.push(
        <rect
          key={i}
          x={x}
          y={y}
          width={s}
          height={s}
          rx={6}
          fill={accent}
          fillOpacity={0.08}
          transform={`rotate(${Math.round(rnd() * 24)} ${x + s / 2} ${y + s / 2})`}
        />,
      );
    } else {
      shapes.push(
        <path
          key={i}
          d={`M${x} ${y} l${s * 0.6} ${-s * 0.35} l0 ${s * 0.7} Z`}
          fill={accent}
          fillOpacity={0.1}
        />,
      );
    }
  }
  return <>{shapes}</>;
}

export function CoverArt({
  image,
  seed,
  className,
}: {
  image: ArticleImage;
  seed: string;
  className?: string;
}) {
  // Bundled static cover (public/images/articles/<slug>.svg) wins over the
  // generated fallback art. These are tiny already-optimized SVGs, so the
  // Next.js image optimizer is skipped via `unoptimized`.
  if (image.src) {
    return (
      <Image
        src={image.src}
        alt={image.alt}
        width={1200}
        height={630}
        unoptimized
        loading="lazy"
        decoding="async"
        style={{ objectFit: "cover", width: "100%", height: "100%" }}
        className={className}
      />
    );
  }

  const tone = TONES[image.cover] ?? TONES.generic;
  return (
    <svg
      viewBox="0 0 1200 630"
      role="img"
      aria-label={image.alt}
      className={className}
      preserveAspectRatio="xMidYMid slice"
    >
      <defs>
        <linearGradient id={`bg-${seed}`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#f4f5f8" />
          <stop offset="55%" stopColor="#fbfbfd" />
          <stop offset="100%" stopColor="#f1f2f7" />
        </linearGradient>
        <radialGradient id={`glow-${seed}`} cx="74%" cy="20%" r="85%">
          <stop offset="0%" stopColor={tone.accent} stopOpacity="0.2" />
          <stop offset="100%" stopColor={tone.accent} stopOpacity="0" />
        </radialGradient>
        <pattern id={`grid-${seed}`} width="44" height="44" patternUnits="userSpaceOnUse">
          <path d="M44 0H0V44" fill="none" stroke="#1b2133" strokeOpacity="0.05" strokeWidth="1" />
        </pattern>
      </defs>

      <rect width="1200" height="630" fill={`url(#bg-${seed})`} />
      <rect width="1200" height="630" fill={`url(#glow-${seed})`} />
      <rect width="1200" height="630" fill={`url(#grid-${seed})`} />
      <Accents seed={seed} accent={tone.accent} />

      {/* accent corner block */}
      <rect x="0" y="0" width="6" height="630" fill={tone.accent} opacity="0.9" />

      {/* category label */}
      <text
        x="86"
        y="92"
        fontFamily="IBM Plex Mono, monospace"
        fontSize="30"
        letterSpacing="9"
        fill="#1b2133"
        fillOpacity="0.55"
      >
        {tone.label}
      </text>

      {/* soft wordmark */}
      <text
        x="86"
        y="470"
        fontFamily="'Space Grotesk', sans-serif"
        fontSize="150"
        fontWeight="700"
        letterSpacing="-2"
        fill="#171a22"
        fillOpacity="0.07"
      >
        TECHHOW
      </text>
    </svg>
  );
}

import Link from "next/link";
import type { Article } from "@/content/types";
import { getAuthorBySlug, getCategoryBySlugSafe } from "@/content";
import { relativeTime, readingMinutes } from "@/lib/format";
import { CoverArt } from "./cover-art";
import { StatusTag, getStatusTag } from "./status-tag";

/**
 * Clean editorial hero. Left: the featured story as a large card with the
 * cover on top and the headline below. Right: compact "Most read" list.
 */
export function Hero({ featured, trending }: { featured: Article; trending: Article[] }) {
  const tag = getStatusTag(featured);
  const author = getAuthorBySlug(featured.author);
  const category = getCategoryBySlugSafe(featured.category);

  return (
    <section className="mx-auto max-w-[1440px] px-4 pt-6 sm:pt-8">
      <div className="grid gap-5 lg:grid-cols-[1.85fr_1fr]">
        {/* Left — featured story */}
        <Link
          href={`/${featured.category}/${featured.slug}`}
          className="group overflow-hidden rounded-2xl border border-line bg-surface shadow-card transition-shadow hover:shadow-none"
        >
          <div className="relative aspect-[16/8] overflow-hidden sm:aspect-[16/7]">
            <CoverArt
              image={featured.image}
              seed={featured.slug}
              className="h-full w-full transition-transform duration-700 group-hover:scale-[1.02]"
            />
            {tag && (
              <div className="absolute left-4 top-4">
                <span className="rounded-full border border-line bg-surface/90 px-3 py-1.5 shadow-sm backdrop-blur-sm">
                  <StatusTag tag={tag} size="lg" />
                </span>
              </div>
            )}
            {featured.sponsored && (
              <span className="absolute right-4 top-4 rounded-full border border-amber/40 bg-surface/90 px-2.5 py-1 font-mono text-[10px] font-bold uppercase tracking-[0.14em] text-amber shadow-sm backdrop-blur-sm">
                Sponsored
              </span>
            )}
          </div>

          <div className="p-5 sm:p-8">
            <div className="mb-3 flex flex-wrap items-center gap-2 font-mono text-[11px] text-muted">
              {category && (
                <span
                  className="rounded-full border border-line px-2.5 py-0.5 font-semibold uppercase tracking-[0.12em]"
                  style={{ color: category.color }}
                >
                  {category.name}
                </span>
              )}
              <span>{author?.name ?? "TechHow Desk"}</span>
              <span aria-hidden="true">·</span>
              <span>{relativeTime(featured.publishedAt)}</span>
              <span aria-hidden="true">·</span>
              <span>{readingMinutes(featured.content)} min read</span>
            </div>
            <h1 className="max-w-3xl font-display text-3xl font-bold text-fg group-hover:text-signal-ink sm:text-5xl">
              {featured.title}
            </h1>
            <p className="mt-3 line-clamp-2 max-w-2xl text-sm leading-relaxed text-muted sm:text-base">
              {featured.excerpt}
            </p>
            <span className="mt-4 inline-flex items-center gap-2 font-mono text-[12px] font-semibold uppercase tracking-[0.12em] text-signal-ink">
              Read the guide <span className="transition-transform group-hover:translate-x-1">→</span>
            </span>
          </div>
        </Link>

        {/* Right — trending list */}
        <aside className="flex flex-col overflow-hidden rounded-2xl border border-line bg-surface shadow-card">
          <div className="flex items-center justify-between border-b border-line px-4 py-3">
            <h2 className="flex items-center gap-2 font-mono text-[12px] font-semibold uppercase tracking-[0.12em] text-signal-ink">
              <span className="status-dot is-trending" />
              Most read
            </h2>
            <Link
              href="/trending"
              className="font-mono text-[11px] uppercase tracking-[0.1em] text-muted transition-colors hover:text-fg"
            >
              View all →
            </Link>
          </div>
          <div className="scroll-slim flex-1 divide-y divide-line overflow-y-auto" style={{ maxHeight: 540 }}>
            {trending.map((item) => (
              <TrendingRow key={item.slug} article={item} />
            ))}
          </div>
        </aside>
      </div>
    </section>
  );
}

function TrendingRow({ article }: { article: Article }) {
  const tag = getStatusTag(article);
  return (
    <Link
      href={`/${article.category}/${article.slug}`}
      className="group flex items-center gap-3 px-4 py-3 transition-colors hover:bg-surface-2"
    >
      <span className="font-display text-xl font-bold text-muted/40 transition-colors group-hover:text-signal">
        {String(article.trendingRank ?? "").padStart(2, "0")}
      </span>
      <div className="relative h-12 w-16 flex-none overflow-hidden rounded-md border border-line">
        <CoverArt image={article.image} seed={article.slug} className="h-full w-full" />
      </div>
      <div className="min-w-0 flex-1">
        <p className="line-clamp-2 text-[13px] font-medium leading-snug text-fg group-hover:text-signal-ink">
          {article.title}
        </p>
        <p className="mt-1 flex items-center gap-2 font-mono text-[10px] uppercase tracking-wider text-muted">
          {relativeTime(article.publishedAt)}
          {tag && (
            <span className="flex items-center gap-1 text-amber">
              <span className={`${tag.kind === "trending" ? "status-dot is-trending" : "status-dot is-updated"}`} />
            </span>
          )}
        </p>
      </div>
    </Link>
  );
}

import Link from "next/link";
import type { Article } from "@/content/types";

/**
 * Quiet "Latest" strip. A simple flex row of the newest titles with a
 * compact signal chip on the left — no animation, no broadcast styling.
 */
export function Ticker({ articles }: { articles: Article[] }) {
  const items = articles.slice(0, 6);

  return (
    <div className="border-b border-line bg-surface">
      <div className="mx-auto flex max-w-[1440px] items-center gap-4 overflow-hidden px-4">
        <span className="flex flex-none items-center gap-1.5 py-2.5 font-mono text-[10px] font-semibold uppercase tracking-[0.14em] text-signal-ink">
          <span className="status-dot is-trending" aria-hidden="true" />
          Latest
        </span>
        <div className="flex min-w-0 flex-1 items-center gap-5 overflow-hidden">
          {items.map((article) => (
            <Link
              key={article.slug}
              href={`/${article.category}/${article.slug}`}
              className="truncate py-2.5 font-mono text-[12px] uppercase tracking-[0.04em] text-muted transition-colors hover:text-signal-ink"
            >
              {article.title}
            </Link>
          ))}
        </div>
      </div>
    </div>
  );
}

