import Link from "next/link";
import { NAV_LINKS } from "@/lib/site";
import { getSearchIndex } from "@/content";
import { getSession } from "@/lib/db/auth";
import { SearchDialog } from "./search-dialog";
import { SearchTrigger } from "./search-trigger";
import { LanguageSelector } from "./language-selector";
import { ThemeToggle } from "./theme-toggle";
import { MobileNav } from "./mobile-nav";

function Logo() {
  return (
    <Link href="/" className="flex items-center gap-2" aria-label="TechHow — home">
      <span className="relative flex h-6 w-6 items-center justify-center rounded-md bg-signal">
        <span className="h-2.5 w-2.5 rounded-[3px] border-2 border-white" />
      </span>
      <span className="font-display text-[1.45rem] font-bold tracking-tight text-fg">
        Tech<span className="text-signal">How</span>
      </span>
    </Link>
  );
}

export async function Header() {
  const searchIndex = getSearchIndex();
  const session = await getSession();

  return (
    <header className="sticky top-0 z-40">
      {/* Main bar */}
      <div className="border-b border-line bg-bg/90 backdrop-blur-md">
        <div className="mx-auto flex h-16 max-w-[1440px] items-center gap-5 px-4">
          <Logo />

          <nav className="hidden items-center gap-5 xl:flex" aria-label="Primary">
            {NAV_LINKS.map((link) => (
              <Link
                key={link.href}
                href={link.href}
                className="whitespace-nowrap font-mono text-[12px] uppercase tracking-[0.06em] text-muted transition-colors hover:text-fg"
              >
                {link.label}
              </Link>
            ))}
          </nav>

          <div className="ml-auto flex items-center gap-2">
            <SearchTrigger />
            <div className="hidden sm:block">
              <LanguageSelector />
            </div>
            <div className="hidden lg:block">
              <ThemeToggle />
            </div>

            {session ? (
              <div className="hidden items-center gap-4 lg:flex">
                {session.role === "admin" && (
                  <Link
                    href="/admin"
                    className="font-mono text-[12px] uppercase tracking-[0.06em] text-signal-ink transition-colors hover:text-signal"
                  >
                    Admin
                  </Link>
                )}
                <Link
                  href="/account"
                  className="flex items-center gap-2 rounded-full border border-line bg-surface py-1 pl-1 pr-3 transition-colors hover:border-signal/40"
                >
                  <span className="flex h-6 w-6 items-center justify-center rounded-full bg-signal font-mono text-[11px] font-bold text-white">
                    {session.name.slice(0, 1).toUpperCase()}
                  </span>
                  <span className="max-w-[140px] truncate font-mono text-[12px] text-fg">{session.name}</span>
                </Link>
                <form action="/api/auth/logout" method="post">
                  <button
                    type="submit"
                    className="font-mono text-[12px] uppercase tracking-[0.06em] text-muted transition-colors hover:text-fg"
                  >
                    Sign out
                  </button>
                </form>
              </div>
            ) : (
              <div className="hidden items-center gap-4 lg:flex">
                <Link
                  href="/login"
                  className="font-mono text-[12px] uppercase tracking-[0.06em] text-muted transition-colors hover:text-fg"
                >
                  Login
                </Link>
                <Link
                  href="/register"
                  className="rounded-md bg-signal px-3.5 py-2 font-mono text-[12px] font-semibold uppercase tracking-[0.06em] text-white transition-opacity hover:opacity-90"
                >
                  Register
                </Link>
              </div>
            )}

            <div className="xl:hidden">
              <MobileNav />
            </div>
          </div>
        </div>
