const { DatabaseSync } = require("node:sqlite");
const db = new DatabaseSync(".data/local.sqlite");
const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all().map((r) => r.name);
console.log("tables:", tables.join(", "));
for (const t of tables) {
  if (/session/.test(t)) {
    const cols = db.prepare(`PRAGMA table_info(${t})`).all().map((c) => c.name);
    console.log(t, "cols:", cols.join(", "));
  }
}
db.close();

const { DatabaseSync } = require("node:sqlite");
const db = new DatabaseSync(".data/local.sqlite");

const del = db.prepare("DELETE FROM sessions WHERE user_id = (SELECT id FROM users WHERE email = ?)");
for (const email of ["test@example.com", "flow@test.com"]) {
  del.run(email);
}
const delUser = db.prepare("DELETE FROM users WHERE email = ?");
const remaining = [];
for (const email of ["test@example.com", "flow@test.com"]) {
  const info = delUser.run(email);
  remaining.push(`${email}: removed ${info.changes}`);
}
const left = db.prepare("SELECT email, role FROM users ORDER BY created_at").all();
console.log(remaining.join(", "));
console.log("users left:", left.map((u) => `${u.email} (${u.role})`).join(", "));
db.close();

