import Link from "next/link";
import type { Article } from "@/content/types";
import { getAuthorBySlug, getCategoryBySlugSafe } from "@/content";
import { relativeTime, readingMinutes } from "@/lib/format";
import { CoverArt } from "./cover-art";
import { StatusTag, getStatusTag } from "./status-tag";

/**
 * Article card. `featured` is the homepage live-feed hero variant;
 * `compact` is the "Trending now" ticker row.
 */
export function ArticleCard({
  article,
  variant = "default",
}: {
  article: Article;
  variant?: "default" | "featured" | "compact";
}) {
  const tag = getStatusTag(article);
  const author = getAuthorBySlug(article.author);
  const category = getCategoryBySlugSafe(article.category);

  if (variant === "compact") {
    return (
      <Link
        href={`/${article.category}/${article.slug}`}
        className="group flex items-center gap-3 rounded-lg border border-transparent px-2 py-2.5 transition-colors hover:border-line hover:bg-surface-2"
      >
        <div className="relative h-11 w-16 flex-none overflow-hidden rounded-md border border-line">
          <CoverArt image={article.image} seed={article.slug} className="h-full w-full" />
        </div>
        <div className="min-w-0 flex-1">
          <p className="line-clamp-2 text-[13px] font-medium leading-snug text-fg group-hover:text-signal-ink">
            {article.title}
          </p>
          <p className="mt-1 font-mono text-[10px] uppercase tracking-wider text-muted">
            {relativeTime(article.publishedAt)}
          </p>
        </div>
        {tag && <StatusTag tag={tag} />}
      </Link>
    );
  }

  return (
    <Link
      href={`/${article.category}/${article.slug}`}
      className={`group flex flex-col overflow-hidden rounded-xl border border-line bg-surface shadow-card transition-shadow hover:shadow-none ${
        variant === "featured" ? "" : "h-full"
      }`}
    >
      <div className={`relative flex-none overflow-hidden ${variant === "featured" ? "aspect-[16/9]" : "aspect-[16/10]"}`}>
        <CoverArt
          image={article.image}
          seed={article.slug}
          className="h-full w-full transition-transform duration-500 group-hover:scale-[1.03]"
        />
        <div className="absolute left-3 top-3 flex items-center gap-2">
          {tag && (
            <span className="rounded-full border border-line bg-bg/80 px-2.5 py-1 backdrop-blur-sm">
              <StatusTag tag={tag} />
            </span>
          )}
        </div>
        {category && (
          <span className="absolute right-3 top-3 rounded-full border border-line bg-bg/80 px-2 py-1 font-mono text-[10px] font-semibold uppercase tracking-[0.14em] text-muted backdrop-blur-sm">
            {category.name}
          </span>
        )}
        {article.sponsored && (
          <span className="absolute bottom-3 right-3 rounded border border-amber/50 bg-bg/80 px-1.5 py-0.5 font-mono text-[9px] font-bold uppercase tracking-[0.14em] text-amber">
            Sponsored
          </span>
        )}
      </div>

      <div className="flex flex-1 flex-col gap-2 p-4">
        <h3
          className={`font-display font-bold leading-tight text-fg transition-colors group-hover:text-signal-ink ${
            variant === "featured" ? "text-2xl sm:text-3xl" : "text-lg"
          }`}
        >
          {article.title}
        </h3>
        {variant === "featured" ? (
          <p className="mt-1 line-clamp-2 text-sm leading-relaxed text-muted">{article.excerpt}</p>
        ) : (
          <p className="line-clamp-2 text-[13px] leading-relaxed text-muted">{article.excerpt}</p>
        )}
        <div className="mt-auto flex items-center gap-2 pt-2 font-mono text-[11px] text-muted">
          <span className="truncate">{author?.name ?? "TechHow Desk"}</span>
          <span aria-hidden="true" className="text-signal">
            ▸
          </span>
          <span className="flex-none">{relativeTime(article.publishedAt)}</span>
          <span aria-hidden="true" className="flex-none text-signal">
            ·
          </span>
          <span className="flex-none">{readingMinutes(article.content)} min read</span>
        </div>
      </div>
    </Link>
  );
}

/**
 * Content model for articles.
 *
 * Phase 1 ships articles as typed TypeScript data (`src/content/articles/`).
 * The model mirrors how a Phase 2 CMS/admin panel would store content as
 * block-based rows, so swapping the source (DB + API) does not change any
 * template. `getAllArticles()` in `src/content/index.ts` is the single
 * access point to replace.
 */

export type CategorySlug =
  | "windows"
  | "macos"
  | "hardware"
  | "software"
  | "internet"
  | "security"
  | "coding"
  | "ai";

/** How-to tutorials carry a difficulty level so readers can pick their entry point. */
export type Difficulty = "beginner" | "intermediate" | "advanced";

export type ArticleStatus = "live" | "breaking" | "updated" | "trending";

/** Status tags carry real recency information, not decoration. */
export type StatusTag =
  | { kind: "live"; label: string }
  | { kind: "breaking"; label: string }
  | { kind: "updated"; minutesAgo: number }
  | { kind: "trending"; label: string };

export type ContentBlock =
  | { type: "p"; text: string }
  | { type: "h2"; text: string }
  | { type: "h3"; text: string }
  | { type: "list"; ordered?: boolean; items: string[] }
  | { type: "quote"; text: string; cite?: string }
  | {
      type: "callout";
      tone: "info" | "warn" | "success";
      title?: string;
      text: string;
    }
  | { type: "table"; columns: string[]; rows: string[][] }
  /** Preformatted code/terminal snippet. Rendered with a copy button. */
  | { type: "code"; lang?: string; text: string }
  /** Full comparison row used inside the "best of" template. */
  | {
      type: "product";
      name: string;
      tagline: string;
      rating: number; // 0–5
      price: string;
      pros: string[];
      cons: string[];
      bestFor: string;
      /** Human-readable label; href resolved from affiliate catalog. */
      affiliateLabel?: string;
      affiliateKey?: string;
      /** Direct tracked URL (replaces catalog lookup when provided). */
      affiliateHref?: string;
    }
  | {
      type: "affiliateCta";
      text: string;
      href: string;
      label: string;
    };

export interface ArticleSource {
  label: string;
  url: string;
}

export interface ArticleImage {
  /** Deterministic cover key (category slug, or a custom theme). */
  cover: CategorySlug | "generic" | "live";
  alt: string;
  credit?: string;
  /**
   * Bundled static cover file (e.g. /images/articles/<slug>.svg). When set,
   * CoverArt renders the file instead of the generated fallback art.
   */
  src?: string;
}

export interface Article {
  slug: string;
  title: string;
  excerpt: string;
  category: CategorySlug;
  tags: string[];
  author: string; // author slug
  publishedAt: string; // ISO date
  updatedAt?: string; // ISO date — drives "● UPDATED" tags
  status?: ArticleStatus;
  /** Top-of-page hero story. Exactly one per homepage. */
  featured?: boolean;
  /** Shown in the homepage "Trending now" ticker. */
  trendingRank?: number;
  image: ArticleImage;
  seo?: { title?: string; description?: string };
  sponsored?: boolean;
  affiliate?: {
    disclosed?: boolean;
    /** When set, an affiliate product catalog table is rendered. */
    catalog?: string;
  };
  related?: string[];
  sources: ArticleSource[];
  content: ContentBlock[];
  /** Tutorial metadata rendered as a header block on the article page. */
  tutorial?: {
    difficulty: Difficulty;
    timeMinutes: number;
    /** Things the reader should already have/known before starting. */
    prerequisites: string[];
    /** "What you'll learn" — rendered as a checklist. */
    learn: string[];
  };
}

export interface Author {
  slug: string;
  name: string;
  role: string;
  bio: string;
  avatarKey: string;
  email?: string;
}

export interface Category {
  slug: CategorySlug;
  name: string;
  short: string;
  description: string;
  /** Subcategories / topic chips shown on the category page header. */
  topics: string[];
  color: string;
}

/** Affiliate catalog: name → product rows for `affiliate.catalog` keys. */
export interface AffiliateProduct {
  name: string;
  tagline: string;
  rating: number;
  price: string;
  bestFor: string;
  pros: string[];
  cons: string[];
  url: string;
  badge?: string;
}

