input.content:
import Link from "next/link";

/**
 * AI Tech logo — a gradient rounded badge with an "AI spark + circuit node"
 * mark, followed by the AI Tech wordmark. Reused in the header, footer,
 * mobile menu and admin shell; the favicon (app/icon.svg) mirrors the mark.
 */

export function LogoMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 32 32" fill="none" className={className} aria-hidden="true">
      <defs>
        <linearGradient id="ait-logo" x1="0" y1="0" x2="32" y2="32" gradientUnits="userSpaceOnUse">
          <stop stopColor="#4f46e5" />
          <stop offset="1" stopColor="#7c3aed" />
        </linearGradient>
      </defs>
      <rect width="32" height="32" rx="9" fill="url(#ait-logo)" />
      <path d="M16 6.5l2.1 5.9 5.9 2.1-5.9 2.1L16 22.5l-2.1-5.9-5.9-2.1 5.9-2.1L16 6.5z" fill="#fff" />
      <path
        d="M26.2 21.6l-2.6 2.6"
        stroke="#fff"
        strokeOpacity="0.75"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
      <path d="M24.6 19.9v3.2M22.6 21.4h3.2" stroke="#fff" strokeOpacity="0.6" strokeWidth="1.6" strokeLinecap="round" />
      <circle cx="26.2" cy="25.6" r="1.9" fill="#fff" />
    </svg>
  );
}

export function Logo({
  size = "md",
  className = "",
}: {
  size?: "sm" | "md" | "lg";
  className?: string;
}) {
  const box = size === "sm" ? "h-6 w-6" : size === "lg" ? "h-10 w-10" : "h-8 w-8";
  const text = size === "sm" ? "text-lg" : size === "lg" ? "text-3xl" : "text-2xl";
  return (
    <Link href="/" className={`flex items-center gap-2 ${className}`} aria-label="AI Tech — home">
      <span className={`relative flex flex-none ${box}`}>
        <LogoMark className="h-full w-full" />
        <span className="absolute -right-0.5 -top-0.5 h-2 w-2 rounded-full bg-amber ring-2 ring-bg" />
      </span>
      <span className={`font-display ${text} font-bold tracking-tight text-fg`}>
        AI<span className="text-signal">Tech</span>
      </span>
    </Link>
  );
}

