import Link from "next/link";
import { NAV_CATEGORIES } from "@/lib/site";
import { getCategories, getSearchIndex } from "@/content";
import { Logo } from "./logo";
import { AccountMenu } from "./account-menu";
import { SearchDialog } from "./search-dialog";
import { SearchTrigger } from "./search-trigger";
import { LanguageSelector } from "./language-selector";
import { ThemeToggle } from "./theme-toggle";
import { MobileNav } from "./mobile-nav";

const UTILITY_LINKS = [
  { href: "/tutorials", label: "All Tutorials" },
  { href: "/trending", label: "Most Popular" },
  { href: "/news", label: "News" },
];

export function Header() {
  const searchIndex = getSearchIndex();
  const categoryColors = new Map(getCategories().map((c) => [c.slug, c.color]));

  return (
    <header className="sticky top-0 z-40">
      {/* Main bar */}
      <div className="border-b border-line bg-bg/90 backdrop-blur-md">
        <div className="mx-auto flex h-16 max-w-[1440px] items-center gap-5 px-4">
          <Logo />

          <div className="ml-auto flex items-center gap-2">
            <SearchTrigger />
            <div className="hidden sm:block">
              <LanguageSelector />
            </div>
            <div className="hidden lg:block">
              <ThemeToggle />
            </div>

            <AccountMenu />

            <div className="xl:hidden">
              <MobileNav />
            </div>
          </div>
        </div>
      </div>

      {/* Category strip — always visible at the top, under the action bar */}
      <div className="border-b border-line bg-surface/70 backdrop-blur-md">
        <nav
          className="mx-auto flex max-w-[1440px] items-center gap-1.5 overflow-x-auto px-4 py-1.5"
          aria-label="Categories"
        >
          {NAV_CATEGORIES.map((c) => (
            <Link
              key={c.slug}
              href={`/${c.slug}`}
              className="inline-flex flex-none items-center gap-1.5 whitespace-nowrap rounded-full border border-line bg-bg/60 px-2.5 py-1 font-mono text-[10px] font-medium uppercase tracking-[0.08em] text-muted transition-colors hover:border-signal/40 hover:text-fg"
            >
              <span
                className="h-1.5 w-1.5 flex-none rounded-full"
                style={{ backgroundColor: categoryColors.get(c.slug) }}
                aria-hidden="true"
              />
              {c.label}
            </Link>
          ))}
          <span className="mx-1 h-4 w-px flex-none bg-line" aria-hidden="true" />
          {UTILITY_LINKS.map((link) => (
            <Link
              key={link.href}
              href={link.href}
              className="flex-none whitespace-nowrap px-1.5 font-mono text-[10px] uppercase tracking-[0.08em] text-muted transition-colors hover:text-fg"
            >
              {link.label}
            </Link>
          ))}
        </nav>
      </div>

      {/* Floating search dialog (lazy, no-op when closed) */}
      <SearchDialog index={searchIndex} />
    </header>
  );
}

