  const [hidden, setHidden] = useState(0);
  const [open, setOpen] = useState(false);
  const barRef = useRef<HTMLElement>(null);
  const widthsRef = useRef<number[]>([]);
  const moreRef = useRef<HTMLButtonElement>(null);

