  const hiddenItems = items.slice(items.length - hidden);
  const moreVisible = hidden > 0;

  function measure() {
    const el = barRef.current;
    if (!el || widthsRef.current.length === 0) return;
    const gap = 18;
    const moreWidth = moreRef.current?.offsetWidth ?? 0;
    let avail = el.clientWidth;
    let used = 0;
    let count = 0;
    for (const w of widthsRef.current) {
      if (used + w + (count > 0 ? gap : 0) + (moreWidth > 0 ? moreWidth + gap : 0) <= avail) {
        used += w + (count > 0 ? gap : 0);
        count++;
      } else break;
