            href={item.href}
            data-nav-item
            hidden={i >= items.length - hidden}
            className={`flex-none whitespace-nowrap font-display text-sm font-bold uppercase tracking-tight text-fg transition-colors hover:text-signal ${
              item.color ? "inline-flex items-center gap-1.5" : ""
            }`}
          >
            {item.color && (
              <span className="h-1.5 w-1.5 rounded-full" style={{ backgroundColor: item.color }} aria-hidden="true" />
            )}
            {item.label}
          </Link>
        ))}

        <button
          ref={moreRef}
          type="button"
          onClick={() => setOpen((v) => !v)}
          className={`${moreVisible ? "" : "invisible"} inline-flex flex-none items-center gap-1 whitespace-nowrap font-display text-sm font-bold uppercase tracking-tight text-muted transition-colors hover:text-fg`}
          aria-haspopup="menu"
          aria-expanded={open}
        >
          More
          <svg width="10" height="10" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path d="M6 9l6 6 6-6" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </button>
      </nav>

      {open && moreVisible && (
        <div className="fixed inset-0 z-50" onClick={() => setOpen(false)}>
          <div className="absolute inset-0" aria-hidden="true" />
          <div
            role="menu"
            className="absolute right-4 top-16 w-64 rounded-xl border border-line bg-bg p-2 shadow-lg"
            onClick={(e) => e.stopPropagation()}
          >
            {hiddenItems.map((item) => (
              <Link key={item.href} href={item.href} role="menuitem" onClick={() => setOpen(false)}
                className="flex items-center gap-2 rounded-lg px-3 py-2.5 font-display text-sm font-bold uppercase tracking-tight text-fg hover:bg-surface-2">
                {item.color && <span className="h-2 w-2 rounded-full" style={{ backgroundColor: item.color }} aria-hidden="true" />}
                {item.label}
              </Link>
            ))}
            {hiddenItems.length > 0 && <div className="my-1 h-px bg-line" />}
            {utilities.map((u) => (
              <Link key={u.href} href={u.href} role="menuitem" onClick={() => setOpen(false)}
                className="block rounded-lg px-3 py-2 text-sm text-muted hover:bg-surface-2 hover:text-fg">
                {u.label}
              </Link>
            ))}
          </div>
        </div>
      )}
    </>
  );
}
