"use client";

import Link from "next/link";
import { useLayoutEffect, useRef, useState } from "react";

export interface NavItem {
  href: string;
  label: string;
  color?: string;
}

/**
 * Big uppercase category links in the header. Items that don't fit the bar
 * automatically move into a "More" dropdown (all remain clickable).
 */
export function CategoryNav({ items, utilities }: { items: NavItem[]; utilities: NavItem[] }) {
  const [hidden, setHidden] = useState(0);
  const [open, setOpen] = useState(false);
  const barRef = useRef<HTMLElement>(null);
  const widthsRef = useRef<number[]>([]);

  const gap = 18;
  const hiddenItems = items.slice(items.length - hidden);
  const moreVisible = hidden > 0;

  function measure() {
    const el = barRef.current;
    if (!el) return;
    const nodes = Array.from(el.querySelectorAll<HTMLElement>("[data-nav-item]"));
    if (widthsRef.current.length !== nodes.length) {
      widthsRef.current = nodes.map((n) => n.offsetWidth);
    } else {
      nodes.forEach((n, i) => {
        if (!n.hidden) widthsRef.current[i] = n.offsetWidth;
      });
    }
    let avail = el.clientWidth;
    let used = 0;
    let count = 0;
    for (const w of widthsRef.current) {
      if (w > 0 && used + w + (count > 0 ? gap : 0) <= avail) {
        used += w + (count > 0 ? gap : 0);
        count++;
      } else break;
    }
    setHidden(items.length - count);
  }

  useLayoutEffect(() => {
    measure();
    const el = barRef.current;
    const ro = new ResizeObserver(() => measure());
    if (el) ro.observe(el);
    window.addEventListener("resize", () => {
      setOpen(false);
      measure();
    });
    const t = window.setTimeout(measure, 400);
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", measure);
      window.clearTimeout(t);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <>
      <nav
        ref={barRef}
        className="flex min-w-0 flex-1 items-center overflow-hidden"
        style={{ gap }}
        aria-label="Categories"
      >
        {items.map((item, i) => (
          <Link
            key={item.href}
            href={item.href}
            data-nav-item
            hidden={i >= items.length - hidden}
            className="inline-flex flex-none items-center gap-1.5 whitespace-nowrap font-display text-base font-bold uppercase tracking-tight text-fg transition-colors hover:text-signal"
          >
            {item.color && (
              <span
                className="h-2 w-2 flex-none rounded-full"
                style={{ backgroundColor: item.color }}
                aria-hidden="true"
              />
            )}
            {item.label}
          </Link>
        ))}
      </nav>

      <div className="relative flex-none">
        <button
          type="button"
          onClick={() => setOpen((v) => !v)}
          className={`${
            moreVisible ? "" : "invisible"
          } inline-flex items-center gap-1 whitespace-nowrap font-display text-base font-bold uppercase tracking-tight text-muted transition-colors hover:text-fg`}
          aria-haspopup="menu"
          aria-expanded={open}
        >
          More
          <svg width="10" height="10" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path d="M6 9l6 6 6-6" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </button>

        {open && moreVisible && (
          <>
            <div className="fixed inset-0 z-40" onClick={() => setOpen(false)} aria-hidden="true" />
            <div
              role="menu"
              className="absolute right-0 top-full z-50 mt-2 w-64 rounded-xl border border-line bg-bg p-2 shadow-xl"
              onClick={(e) => e.stopPropagation()}
            >
              {hiddenItems.map((item) => (
                <Link
                  key={item.href}
                  href={item.href}
                  role="menuitem"
                  onClick={() => setOpen(false)}
                  className="flex items-center gap-2 rounded-lg px-3 py-2.5 font-display text-sm font-bold uppercase tracking-tight text-fg hover:bg-surface-2"
                >
                  {item.color && (
                    <span
                      className="h-2 w-2 flex-none rounded-full"
                      style={{ backgroundColor: item.color }}
                      aria-hidden="true"
                    />
                  )}
                  {item.label}
                </Link>
              ))}
              <div className="my-1 h-px bg-line" aria-hidden="true" />
              {utilities.map((u) => (
                <Link
                  key={u.href}
                  href={u.href}
                  role="menuitem"
                  onClick={() => setOpen(false)}
                  className="block rounded-lg px-3 py-2 text-sm text-muted hover:bg-surface-2 hover:text-fg"
                >
                  {u.label}
                </Link>
              ))}
            </div>
          </>
        )}
      </div>
    </>
  );
}

